$pageTitle = "The Works of William Shakespeare (Cambridge Ed., Vol. 7) - ACT III. | Hesten's Learning";
?>
<div class="cdn-book-reader-content">
    <div class="lexile-version active" data-lexile="original" data-lexile-label="Original (1320L)">
        <h2>ACT III.</h2>


<h3><span class="smcap">Scene I.</span> <i>A public place.</i><a id="FNanchor_730_730"></a><a class="fnanchor pginternal" href="#Footnote_730_730">[730]</a></h3>

<p class="directcenter"><i>Enter</i> <span class="smcap">Mercutio, Benvolio</span>, Page, <i>and</i> Servants.<a id="FNanchor_731_731"></a><a class="fnanchor pginternal" href="#Footnote_731_731">[731]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Ben.</i> I pray thee, good Mercutio, let's retire:<br></span>
<span class="i0">The day is hot, the Capulets abroad,<a id="FNanchor_732_732"></a><a class="fnanchor pginternal" href="#Footnote_732_732">[732]</a><br></span>
<span class="i0">And, if we meet, we shall not 'scape a brawl;<a id="FNanchor_733_733"></a><a class="fnanchor pginternal" href="#Footnote_733_733">[733]</a><a id="FNanchor_734_734"></a><a class="fnanchor pginternal" href="#Footnote_734_734">[734]</a><br></span>
<span class="i0">For now these hot days is the mad blood stirring.<a class="fnanchor pginternal" href="#Footnote_734_734">[734]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Thou art like one of those fellows that when he<a id="FNanchor_735_735"></a><a class="fnanchor pginternal" href="#Footnote_735_735">[735]</a>     <span class="linenum">5</span><br></span>
<span class="i0">enters the confines of a tavern claps me his sword upon the<br></span>
<span class="i0">table, and says 'God send me no need of thee!' and by the<br></span>
<span class="i0">operation of the second cup draws it on the drawer, when<a id="FNanchor_736_736"></a><a class="fnanchor pginternal" href="#Footnote_736_736">[736]</a><br></span>
<span class="i0">indeed there is no need.<br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i> Am I like such a fellow?                                <span class="linenum">10</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Come, come, thou art as hot a Jack in thy mood<br></span>
<span class="i0">as any in Italy, and as soon moved to be moody and as<br></span>
<span class="i0">soon moody to be moved.<br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i> And what to?<a id="FNanchor_737_737"></a><a class="fnanchor pginternal" href="#Footnote_737_737">[737]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Nay, an there were two such, we should have<a id="FNanchor_738_738"></a><a class="fnanchor pginternal" href="#Footnote_738_738">[738]</a>        <span class="linenum">15</span><br></span>
<span class="i0">none shortly, for one would kill the other. Thou! why, thou<br></span>
<span class="i0">wilt quarrel with a man that hath a hair more, or a hair<br></span>
<span class="i0">less, in his beard than thou hast: thou wilt quarrel with a<br></span>
<span class="i0">man for cracking nuts, having no other reason but because<br></span><span class="pagenum"><a id="Page_65">[Pg 65]</a></span>
<span class="i0">thou hast hazel eyes; what eye, but such an eye, would spy          <span class="linenum">20</span><br></span>
<span class="i0">out such a quarrel? thy head is as full of quarrels as an<br></span>
<span class="i0">egg is full of meat, and yet thy head hath been beaten as<br></span>
<span class="i0">addle as an egg for quarrelling: thou hast quarrelled with<br></span>
<span class="i0">a man for coughing in the street, because he hath wakened<br></span>
<span class="i0">thy dog that hath lain asleep in the sun: didst thou not            <span class="linenum">25</span><br></span>
<span class="i0">fall out with a tailor for wearing his new doublet before<br></span>
<span class="i0">Easter? with another, for tying his new shoes with old<br></span>
<span class="i0">riband? and yet thou wilt tutor me from quarrelling!<a id="FNanchor_739_739"></a><a class="fnanchor pginternal" href="#Footnote_739_739">[739]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i> An I were so apt to quarrel as thou art, any man<a id="FNanchor_740_740"></a><a class="fnanchor pginternal" href="#Footnote_740_740">[740]</a><br></span>
<span class="i0">should buy the fee-simple of my life for an hour and a              <span class="linenum">30</span><br></span>
<span class="i0">quarter.<br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> The fee-simple! O simple!<br></span>
</div></div>

<p class="directcenter"><i>Enter</i> <span class="smcap">Tybalt</span> <i>and others</i>.
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Ben.</i> By my head, here come the Capulets.<a id="FNanchor_741_741"></a><a class="fnanchor pginternal" href="#Footnote_741_741">[741]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> By my heel, I care not.<a id="FNanchor_742_742"></a><a class="fnanchor pginternal" href="#Footnote_742_742">[742]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> Follow me close, for I will speak to them.              <span class="linenum">35</span><br></span>
<span class="i0">Gentlemen, good den: a word with one of you.<br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> And but one word with one of us? couple it with<a id="FNanchor_743_743"></a><a class="fnanchor pginternal" href="#Footnote_743_743">[743]</a><br></span>
<span class="i0">something; make it a word and a blow.<br></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> You shall find me apt enough to that, sir, an you<a id="FNanchor_744_744"></a><a class="fnanchor pginternal" href="#Footnote_744_744">[744]</a><br></span>
<span class="i0">will give me occasion.<a id="FNanchor_745_745"></a><a class="fnanchor pginternal" href="#Footnote_745_745">[745]</a>                                         <span class="linenum">40</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Could you not take some occasion without giving?<br></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> Mercutio, thou consort'st with Romeo,—<a id="FNanchor_746_746"></a><a class="fnanchor pginternal" href="#Footnote_746_746">[746]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Consort! what, dost thou make us minstrels? an<a id="FNanchor_747_747"></a><a class="fnanchor pginternal" href="#Footnote_747_747">[747]</a><br></span>
<span class="i0">thou make minstrels of us, look to hear nothing but discords:<br></span><span class="pagenum"><a id="Page_66">[Pg 66]</a></span>
<span class="i0">here's my fiddlestick; here's that shall make you                   <span class="linenum">45</span><br></span>
<span class="i0">dance. 'Zounds, consort!<a id="FNanchor_748_748"></a><a class="fnanchor pginternal" href="#Footnote_748_748">[748]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i> We talk here in the public haunt of men:<br></span>
<span class="i0">Either withdraw unto some private place,<br></span>
<span class="i0">Or reason coldly of your grievances,<a id="FNanchor_749_749"></a><a class="fnanchor pginternal" href="#Footnote_749_749">[749]</a><br></span>
<span class="i0">Or else depart; here all eyes gaze on us.                           <span class="linenum">50</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Men's eyes were made to look, and let them gaze;<br></span>
<span class="i0">I will not budge for no man's pleasure, I.<br></span>
</div></div>

<p class="directcenter"><i>Enter</i> <span class="smcap">Romeo</span>.
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Tyb.</i> Well, peace be with you, sir: here comes my man.<br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> But I'll be hang'd, sir, if he wear your livery:<br></span>
<span class="i0">Marry, go before to field, he'll be your follower;<a id="FNanchor_750_750"></a><a class="fnanchor pginternal" href="#Footnote_750_750">[750]</a>             <span class="linenum">55</span><br></span>
<span class="i0">Your worship in that sense may call him man.<br></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> Romeo, the love I bear thee can afford<a id="FNanchor_751_751"></a><a class="fnanchor pginternal" href="#Footnote_751_751">[751]</a><br></span>
<span class="i0">No better term than this,—thou art a villain.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Tybalt, the reason that I have to love thee<a id="FNanchor_752_752"></a><a class="fnanchor pginternal" href="#Footnote_752_752">[752]</a><br></span>
<span class="i0">Doth much excuse the appertaining rage<a id="FNanchor_753_753"></a><a class="fnanchor pginternal" href="#Footnote_753_753">[753]</a>                         <span class="linenum">60</span><br></span>
<span class="i0">To such a greeting: villain am I none;<a id="FNanchor_754_754"></a><a class="fnanchor pginternal" href="#Footnote_754_754">[754]</a><br></span>
<span class="i0">Therefore farewell; I see thou know'st me not.<a id="FNanchor_755_755"></a><a class="fnanchor pginternal" href="#Footnote_755_755">[755]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> Boy, this shall not excuse the injuries<a id="FNanchor_756_756"></a><a class="fnanchor pginternal" href="#Footnote_756_756">[756]</a><br></span>
<span class="i0">That thou hast done me; therefore turn and draw.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> I do protest, I never injured thee,<a id="FNanchor_757_757"></a><a class="fnanchor pginternal" href="#Footnote_757_757">[757]</a>                <span class="linenum">65</span><br></span>
<span class="i0">But love thee better than thou canst devise<a id="FNanchor_758_758"></a><a class="fnanchor pginternal" href="#Footnote_758_758">[758]</a><br></span>
<span class="i0">Till thou shalt know the reason of my love:<br></span>
<span class="i0">And so, good Capulet,—which name I tender<br></span>
<span class="i0">As dearly as mine own,—be satisfied.<a id="FNanchor_759_759"></a><a class="fnanchor pginternal" href="#Footnote_759_759">[759]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> O calm, dishonourable, vile submission!<a id="FNanchor_760_760"></a><a class="fnanchor pginternal" href="#Footnote_760_760">[760]</a>            <span class="linenum">70</span><br></span>
<span class="i0">Alla stoccata carries it away.<a id="FNanchor_761_761"></a><a class="fnanchor pginternal" href="#Footnote_761_761">[761]</a>         <span class="directline">[<i>Draws.</i><br></span></span>
<span class="i0">Tybalt, you rat-catcher, will you walk?<a id="FNanchor_762_762"></a><a class="fnanchor pginternal" href="#Footnote_762_762">[762]</a><br></span><span class="pagenum"><a id="Page_67">[Pg 67]</a></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> What wouldst thou have with me?<a id="FNanchor_763_763"></a><a class="fnanchor pginternal" href="#Footnote_763_763">[763]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Good king of cats, nothing but one of your nine<br></span>
<span class="i0">lives, that I mean to make bold withal, and, as you shall           <span class="linenum">75</span><br></span>
<span class="i0">use me hereafter, dry-beat the rest of the eight. Will you<a id="FNanchor_764_764"></a><a class="fnanchor pginternal" href="#Footnote_764_764">[764]</a><br></span>
<span class="i0">pluck your sword out of his pilcher by the ears? make<a id="FNanchor_765_765"></a><a class="fnanchor pginternal" href="#Footnote_765_765">[765]</a><br></span>
<span class="i0">haste, lest mine be about your ears ere it be out.<br></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> I am for you.<a id="FNanchor_766_766"></a><a class="fnanchor pginternal" href="#Footnote_766_766">[766]</a>                        <span class="directline">[<i>Drawing.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Gentle Mercutio, put thy rapier up.                     <span class="linenum">80</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Come, sir, your passado.<a id="FNanchor_767_767"></a><a class="fnanchor pginternal" href="#Footnote_767_767">[767]</a>      <span class="directline">[<i>They fight.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Draw, Benvolio; beat down their weapons.<a id="FNanchor_768_768"></a><a class="fnanchor pginternal" href="#Footnote_768_768">[768]</a><a id="FNanchor_769_769"></a><a class="fnanchor pginternal" href="#Footnote_769_769">[769]</a><br></span>
<span class="i0">Gentlemen, for shame, forbear this outrage!<a class="fnanchor pginternal" href="#Footnote_769_769">[769]</a><br></span>
<span class="i0">Tybalt, Mercutio, the prince expressly hath<a class="fnanchor pginternal" href="#Footnote_769_769">[769]</a><a id="FNanchor_770_770"></a><a class="fnanchor pginternal" href="#Footnote_770_770">[770]</a><br></span>
<span class="i0">Forbid this bandying in Verona streets:<a class="fnanchor pginternal" href="#Footnote_769_769">[769]</a><a id="FNanchor_771_771"></a><a class="fnanchor pginternal" href="#Footnote_771_771">[771]</a><a id="FNanchor_772_772"></a><a class="fnanchor pginternal" href="#Footnote_772_772">[772]</a><a id="FNanchor_773_773"></a><a class="fnanchor pginternal" href="#Footnote_773_773">[773]</a>        <span class="linenum">85</span><br></span>
<span class="i0">Hold, Tybalt! good Mercutio!<a class="fnanchor pginternal" href="#Footnote_769_769">[769]</a><a class="fnanchor pginternal" href="#Footnote_772_772">[772]</a><a id="FNanchor_774_774"></a><a class="fnanchor pginternal" href="#Footnote_774_774">[774]</a><br></span>
</div></div>

<p class="directright">[<i>Tybalt under Romeo's arm stabs Mercutio and</i>
<i>flies with his followers.</i></p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Mer.</i>                       I am hurt;<a id="FNanchor_775_775"></a><a class="fnanchor pginternal" href="#Footnote_775_775">[775]</a><br></span>
<span class="i0">A plague o' both your houses! I am sped:<br></span>
<span class="i0">Is he gone, and hath nothing?<br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i>                        What, art thou hurt?<br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Ay, ay, a scratch, a scratch; marry, 'tis enough.<br></span>
<span class="i0">Where is my page? Go, villain, fetch a surgeon.<a id="FNanchor_776_776"></a><a class="fnanchor pginternal" href="#Footnote_776_776">[776]</a>                <span class="linenum">90</span><br></span><span class="pagenum"><a id="Page_68">[Pg 68]</a></span>
</div></div>

<p class="directright">[<i>Exit Page.</i></p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Rom.</i> Courage, man; the hurt cannot be much.<br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> No, 'tis not so deep as a well, nor so wide as a<br></span>
<span class="i0">church-door; but 'tis enough, 'twill serve: ask for me to-morrow,<br></span>
<span class="i0">and you shall find me a grave man. I am peppered,<br></span>
<span class="i0">I warrant, for this world. A plague o' both your<a id="FNanchor_777_777"></a><a class="fnanchor pginternal" href="#Footnote_777_777">[777]</a>               <span class="linenum">95</span><br></span>
<span class="i0">houses! 'Zounds, a dog, a rat, a mouse, a cat, to scratch a<a id="FNanchor_778_778"></a><a class="fnanchor pginternal" href="#Footnote_778_778">[778]</a><br></span>
<span class="i0">man to death! a braggart, a rogue, a villain, that fights by<br></span>
<span class="i0">the book of arithmetic! Why the devil came you between<a id="FNanchor_779_779"></a><a class="fnanchor pginternal" href="#Footnote_779_779">[779]</a><br></span>
<span class="i0">us? I was hurt under your arm.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> I thought all for the best.                            <span class="linenum">100</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Mer.</i> Help me into some house, Benvolio,<br></span>
<span class="i0">Or I shall faint. A plague o' both your houses!<a id="FNanchor_780_780"></a><a class="fnanchor pginternal" href="#Footnote_780_780">[780]</a><br></span>
<span class="i0">They have made worms' meat of me: I have it,<a id="FNanchor_781_781"></a><a class="fnanchor pginternal" href="#Footnote_781_781">[781]</a><a id="FNanchor_782_782"></a><a class="fnanchor pginternal" href="#Footnote_782_782">[782]</a><br></span>
<span class="i0">And soundly too: your houses!<a class="fnanchor pginternal" href="#Footnote_781_781">[781]</a><a id="FNanchor_783_783"></a><a class="fnanchor pginternal" href="#Footnote_783_783">[783]</a><br></span>
</div></div>

<p class="directright">[<i>Exeunt Mercutio and Benvolio.</i><a id="FNanchor_784_784"></a><a class="fnanchor pginternal" href="#Footnote_784_784">[784]</a></p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Rom.</i> This gentleman, the prince's near ally,<a id="FNanchor_785_785"></a><a class="fnanchor pginternal" href="#Footnote_785_785">[785]</a>           <span class="linenum">105</span><br></span>
<span class="i0">My very friend, hath got this mortal hurt<a id="FNanchor_786_786"></a><a class="fnanchor pginternal" href="#Footnote_786_786">[786]</a><br></span>
<span class="i0">In my behalf; my reputation stain'd<a id="FNanchor_787_787"></a><a class="fnanchor pginternal" href="#Footnote_787_787">[787]</a><br></span>
<span class="i0">With Tybalt's slander,—Tybalt, that an hour<br></span>
<span class="i0">Hath been my kinsman: O sweet Juliet,<a id="FNanchor_788_788"></a><a class="fnanchor pginternal" href="#Footnote_788_788">[788]</a><br></span>
<span class="i0">Thy beauty hath made me effeminate,                                <span class="linenum">110</span><br></span>
<span class="i0">And in my temper soften'd valour's steel!<a id="FNanchor_789_789"></a><a class="fnanchor pginternal" href="#Footnote_789_789">[789]</a><br></span>
</div></div>

<p><span class="pagenum"><a id="Page_69">[Pg 69]</a></span></p>

<p class="directcenter"><i>Re-enter</i> <span class="smcap">Benvolio</span>.
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Ben.</i> O Romeo, Romeo, brave Mercutio's dead!<a id="FNanchor_790_790"></a><a class="fnanchor pginternal" href="#Footnote_790_790">[790]</a><br></span>
<span class="i0">That gallant spirit hath aspired the clouds,<br></span>
<span class="i0">Which too untimely here did scorn the earth.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> This day's black fate on more days doth depend;<a id="FNanchor_791_791"></a><a class="fnanchor pginternal" href="#Footnote_791_791">[791]</a>   <span class="linenum">115</span><br></span>
<span class="i0">This but begins the woe others must end.<a id="FNanchor_792_792"></a><a class="fnanchor pginternal" href="#Footnote_792_792">[792]</a><a id="FNanchor_793_793"></a><a class="fnanchor pginternal" href="#Footnote_793_793">[793]</a><br></span>
</div></div>

<p class="directcenter"><i>Re-enter</i> <span class="smcap">Tybalt</span>.
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Ben.</i> Here comes the furious Tybalt back again.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Alive, in triumph! and Mercutio slain!<a id="FNanchor_794_794"></a><a class="fnanchor pginternal" href="#Footnote_794_794">[794]</a><br></span>
<span class="i0">Away to heaven, respective lenity,<br></span>
<span class="i0">And fire-eyed fury be my conduct now!<a id="FNanchor_795_795"></a><a class="fnanchor pginternal" href="#Footnote_795_795">[795]</a>                         <span class="linenum">120</span><br></span>
<span class="i0">Now, Tybalt, take the 'villain' back again<br></span>
<span class="i0">That late thou gavest me; for Mercutio's soul<br></span>
<span class="i0">Is but a little way above our heads,<br></span>
<span class="i0">Staying for thine to keep him company:<br></span>
<span class="i0">Either thou, or I, or both, must go with him.<a id="FNanchor_796_796"></a><a class="fnanchor pginternal" href="#Footnote_796_796">[796]</a>                 <span class="linenum">125</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Tyb.</i> Thou, wretched boy, that didst consort him here,<br></span>
<span class="i0">Shalt with him hence.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i>                This shall determine that.<br></span>
</div></div>

<p class="directright">[<i>They fight; Tybalt falls.</i></p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Ben.</i> Romeo, away, be gone!<br></span>
<span class="i0">The citizens are up, and Tybalt slain:<br></span>
<span class="i0">Stand not amazed: the prince will doom thee death                  <span class="linenum">130</span><br></span>
<span class="i0">If thou art taken: hence, be gone, away!<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> O, I am fortune's fool!<br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i>                         Why dost thou stay?<br></span>
</div></div>

<p class="directright">[<i>Exit Romeo.</i></p>

<p><span class="pagenum"><a id="Page_70">[Pg 70]</a></span></p>

<p class="directcenter"><i>Enter</i> Citizens, &amp;c.
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>First Cit.</i> Which way ran he that kill'd Mercutio?<a id="FNanchor_797_797"></a><a class="fnanchor pginternal" href="#Footnote_797_797">[797]</a><br></span>
<span class="i0">Tybalt, that murderer, which way ran he?<a id="FNanchor_798_798"></a><a class="fnanchor pginternal" href="#Footnote_798_798">[798]</a><a id="FNanchor_799_799"></a><a class="fnanchor pginternal" href="#Footnote_799_799">[799]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i> There lies that Tybalt.<br></span>
</div><div class="stanza">
<span class="i0"><i>First Cit.</i>                   Up, sir, go with me;<a class="fnanchor pginternal" href="#Footnote_799_799">[799]</a><a id="FNanchor_800_800"></a><a class="fnanchor pginternal" href="#Footnote_800_800">[800]</a><span class="linenum">135</span><br></span>
<span class="i0">I charge thee in the prince's name, obey.<a id="FNanchor_801_801"></a><a class="fnanchor pginternal" href="#Footnote_801_801">[801]</a><br></span>
</div></div>

<p class="directcenter"><i>Enter</i> Prince, <i>attended</i>; <span class="smcap">Montague, Capulet</span>, <i>their</i> Wives,
<i>and others</i>.
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Prin.</i> Where are the vile beginners of this fray?<a id="FNanchor_802_802"></a><a class="fnanchor pginternal" href="#Footnote_802_802">[802]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i> O noble prince, I can discover all<a id="FNanchor_803_803"></a><a class="fnanchor pginternal" href="#Footnote_803_803">[803]</a><br></span>
<span class="i0">The unlucky manage of this fatal brawl:<br></span>
<span class="i0">There lies the man, slain by young Romeo,                          <span class="linenum">140</span><br></span>
<span class="i0">That slew thy kinsman, brave Mercutio.<a id="FNanchor_804_804"></a><a class="fnanchor pginternal" href="#Footnote_804_804">[804]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Tybalt, my cousin! O my brother's child!<a id="FNanchor_805_805"></a><a class="fnanchor pginternal" href="#Footnote_805_805">[805]</a><br></span>
<span class="i0">O prince! O cousin! husband! O, the blood is spilt<a id="FNanchor_806_806"></a><a class="fnanchor pginternal" href="#Footnote_806_806">[806]</a><br></span>
<span class="i0">Of my dear kinsman! Prince, as thou art true,<br></span>
<span class="i0">For blood of ours, shed blood of Montague.                         <span class="linenum">145</span><br></span>
<span class="i0">O cousin, cousin!<a id="FNanchor_807_807"></a><a class="fnanchor pginternal" href="#Footnote_807_807">[807]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Prin.</i> Benvolio, who began this bloody fray?<a id="FNanchor_808_808"></a><a class="fnanchor pginternal" href="#Footnote_808_808">[808]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Ben.</i> Tybalt, here slain, whom Romeo's hand did slay;<br></span>
<span class="i0">Romeo that spoke him fair, bid him bethink<a id="FNanchor_809_809"></a><a class="fnanchor pginternal" href="#Footnote_809_809">[809]</a><br></span>
<span class="i0">How nice the quarrel was, and urged withal                         <span class="linenum">150</span><br></span>
<span class="i0">Your high displeasure: all this uttered<br></span><span class="pagenum"><a id="Page_71">[Pg 71]</a></span>
<span class="i0">With gentle breath, calm look, knees humbly bow'd,<a id="FNanchor_810_810"></a><a class="fnanchor pginternal" href="#Footnote_810_810">[810]</a><br></span>
<span class="i0">Could not take truce with the unruly spleen<a id="FNanchor_811_811"></a><a class="fnanchor pginternal" href="#Footnote_811_811">[811]</a><br></span>
<span class="i0">Of Tybalt deaf to peace, but that he tilts<a id="FNanchor_812_812"></a><a class="fnanchor pginternal" href="#Footnote_812_812">[812]</a><br></span>
<span class="i0">With piercing steel at bold Mercutio's breast;                     <span class="linenum">155</span><br></span>
<span class="i0">Who, all as hot, turns deadly point to point,<br></span>
<span class="i0">And, with a martial scorn, with one hand beats<br></span>
<span class="i0">Cold death aside, and with the other sends<br></span>
<span class="i0">It back to Tybalt, whose dexterity<br></span>
<span class="i0">Retorts it: Romeo he cries aloud,<a id="FNanchor_813_813"></a><a class="fnanchor pginternal" href="#Footnote_813_813">[813]</a>                             <span class="linenum">160</span><br></span>
<span class="i0">'Hold, friends! friends, part!' and, swifter than his tongue,<br></span>
<span class="i0">His agile arm beats down their fatal points,<a id="FNanchor_814_814"></a><a class="fnanchor pginternal" href="#Footnote_814_814">[814]</a><br></span>
<span class="i0">And 'twixt them rushes; underneath whose arm<br></span>
<span class="i0">An envious thrust from Tybalt hit the life<br></span>
<span class="i0">Of stout Mercutio, and then Tybalt fled:                           <span class="linenum">165</span><br></span>
<span class="i0">But by and by comes back to Romeo,<br></span>
<span class="i0">Who had but newly entertain'd revenge,<a id="FNanchor_815_815"></a><a class="fnanchor pginternal" href="#Footnote_815_815">[815]</a><br></span>
<span class="i0">And to't they go like lightning: for, ere I<a id="FNanchor_816_816"></a><a class="fnanchor pginternal" href="#Footnote_816_816">[816]</a><br></span>
<span class="i0">Could draw to part them, was stout Tybalt slain;<br></span>
<span class="i0">And, as he fell, did Romeo turn and fly;<a id="FNanchor_817_817"></a><a class="fnanchor pginternal" href="#Footnote_817_817">[817]</a>                      <span class="linenum">170</span><br></span>
<span class="i0">This is the truth, or let Benvolio die.<br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> He is a kinsman to the Montague,<a class="fnanchor pginternal" href="#Footnote_804_804">[804]</a><a id="FNanchor_818_818"></a><a class="fnanchor pginternal" href="#Footnote_818_818">[818]</a><br></span>
<span class="i0">Affection makes him false, he speaks not true:<br></span>
<span class="i0">Some twenty of them fought in this black strife,<br></span>
<span class="i0">And all those twenty could but kill one life.                      <span class="linenum">175</span><br></span>
<span class="i0">I beg for justice, which thou, prince, must give;<br></span>
<span class="i0">Romeo slew Tybalt, Romeo must not live.<br></span>
</div><div class="stanza">
<span class="i0"><i>Prin.</i> Romeo slew him, he slew Mercutio;<br></span>
<span class="i0">Who now the price of his dear blood doth owe?<a id="FNanchor_819_819"></a><a class="fnanchor pginternal" href="#Footnote_819_819">[819]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Mon.</i> Not Romeo, prince, he was Mercutio's friend;<a id="FNanchor_820_820"></a><a class="fnanchor pginternal" href="#Footnote_820_820">[820]</a>      <span class="linenum">180</span><br></span>
<span class="i0">His fault concludes but what the law should end,<br></span>
<span class="i0">The life of Tybalt.<br></span><span class="pagenum"><a id="Page_72">[Pg 72]</a></span>
</div><div class="stanza">
<span class="i0"><i>Prin.</i>             And for that offence<br></span>
<span class="i0">Immediately we do exile him hence:<br></span>
<span class="i0">I have an interest in your hate's proceeding,<a id="FNanchor_821_821"></a><a class="fnanchor pginternal" href="#Footnote_821_821">[821]</a><br></span>
<span class="i0">My blood for your rude brawls doth lie a-bleeding;                 <span class="linenum">185</span><br></span>
<span class="i0">But I'll amerce you with so strong a fine,<br></span>
<span class="i0">That you shall all repent the loss of mine:<br></span>
<span class="i0">I will be deaf to pleading and excuses;<a id="FNanchor_822_822"></a><a class="fnanchor pginternal" href="#Footnote_822_822">[822]</a><br></span>
<span class="i0">Nor tears nor prayers shall purchase out abuses:<a id="FNanchor_823_823"></a><a class="fnanchor pginternal" href="#Footnote_823_823">[823]</a><br></span>
<span class="i0">Therefore use none: let Romeo hence in haste,                      <span class="linenum">190</span><br></span>
<span class="i0">Else, when he's found, that hour is his last.<a id="FNanchor_824_824"></a><a class="fnanchor pginternal" href="#Footnote_824_824">[824]</a><br></span>
<span class="i0">Bear hence this body, and attend our will:<br></span>
<span class="i0">Mercy but murders, pardoning those that kill.       <span class="directline">[<i>Exeunt.</i><a id="FNanchor_825_825"></a><a class="fnanchor pginternal" href="#Footnote_825_825">[825]</a><br></span></span>
</div></div>


<h3><span class="smcap">Scene II.</span> <i>Capulet's orchard.</i><a id="FNanchor_826_826"></a><a class="fnanchor pginternal" href="#Footnote_826_826">[826]</a></h3>

<p class="directcenter"><i>Enter</i> <span class="smcap">Juliet</span>.<a id="FNanchor_827_827"></a><a class="fnanchor pginternal" href="#Footnote_827_827">[827]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Jul.</i> Gallop apace, you fiery-footed steeds,<br></span>
<span class="i0">Towards Phœbus' lodging: such a waggoner<a id="FNanchor_828_828"></a><a class="fnanchor pginternal" href="#Footnote_828_828">[828]</a><br></span>
<span class="i0">As Phaethon would whip you to the west,<a id="FNanchor_829_829"></a><a class="fnanchor pginternal" href="#Footnote_829_829">[829]</a><br></span>
<span class="i0">And bring in cloudy night immediately.<br></span>
<span class="i0">Spread thy close curtain, love-performing night,                     <span class="linenum">5</span><br></span>
<span class="i0">That runaway's eyes may wink, and Romeo<a id="FNanchor_830_830"></a><a class="fnanchor pginternal" href="#Footnote_830_830">[830]</a><br></span>
<span class="i0">Leap to these arms, untalk'd of and unseen.<a id="FNanchor_831_831"></a><a class="fnanchor pginternal" href="#Footnote_831_831">[831]</a><br></span><span class="pagenum"><a id="Page_73">[Pg 73]</a></span>
<span class="i0">Lovers can see to do their amorous rites<a id="FNanchor_832_832"></a><a class="fnanchor pginternal" href="#Footnote_832_832">[832]</a><br></span>
<span class="i0">By their own beauties; or, if love be blind,<a id="FNanchor_833_833"></a><a class="fnanchor pginternal" href="#Footnote_833_833">[833]</a><br></span>
<span class="i0">It best agrees with night. Come, civil night,                       <span class="linenum">10</span><br></span>
<span class="i0">Thou sober-suited matron, all in black,<a id="FNanchor_834_834"></a><a class="fnanchor pginternal" href="#Footnote_834_834">[834]</a><br></span>
<span class="i0">And learn me how to lose a winning match,<br></span>
<span class="i0">Play'd for a pair of stainless maidenhoods:<a id="FNanchor_835_835"></a><a class="fnanchor pginternal" href="#Footnote_835_835">[835]</a><br></span>
<span class="i0">Hood my unmann'd blood bating in my cheeks<a id="FNanchor_836_836"></a><a class="fnanchor pginternal" href="#Footnote_836_836">[836]</a><br></span>
<span class="i0">With thy black mantle, till strange love grown bold<a id="FNanchor_837_837"></a><a class="fnanchor pginternal" href="#Footnote_837_837">[837]</a>            <span class="linenum">15</span><br></span>
<span class="i0">Think true love acted simple modesty.<a id="FNanchor_838_838"></a><a class="fnanchor pginternal" href="#Footnote_838_838">[838]</a><br></span>
<span class="i0">Come, night, come, Romeo, come, thou day in night;<br></span>
<span class="i0">For thou wilt lie upon the wings of night<br></span>
<span class="i0">Whiter than new snow on a raven's back.<a id="FNanchor_839_839"></a><a class="fnanchor pginternal" href="#Footnote_839_839">[839]</a><br></span>
<span class="i0">Come, gentle night, come, loving, black-brow'd night,               <span class="linenum">20</span><br></span>
<span class="i0">Give me my Romeo; and, when he shall die,<a id="FNanchor_840_840"></a><a class="fnanchor pginternal" href="#Footnote_840_840">[840]</a><br></span>
<span class="i0">Take him and cut him out in little stars,<br></span>
<span class="i0">And he will make the face of heaven so fine<br></span>
<span class="i0">That all the world will be in love with night<a id="FNanchor_841_841"></a><a class="fnanchor pginternal" href="#Footnote_841_841">[841]</a><br></span>
<span class="i0">And pay no worship to the garish sun.                               <span class="linenum">25</span><br></span>
<span class="i0">O, I have bought the mansion of a love,<br></span>
<span class="i0">But not possess'd it, and, though I am sold,<br></span>
<span class="i0">Not yet enjoy'd; so tedious is this day<br></span>
<span class="i0">As is the night before some festival<br></span>
<span class="i0">To an impatient child that hath new robes                           <span class="linenum">30</span><br></span>
<span class="i0">And may not wear them. O, here comes my nurse,<br></span><span class="pagenum"><a id="Page_74">[Pg 74]</a></span>
<span class="i0">And she brings news, and every tongue that speaks<br></span>
<span class="i0">But Romeo's name speaks heavenly eloquence.<br></span>
</div></div>

<p class="directcenter"><i>Enter</i> Nurse, <i>with cords</i>.<a id="FNanchor_842_842"></a><a class="fnanchor pginternal" href="#Footnote_842_842">[842]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0">Now, nurse, what news? What hast thou there? the cords<a id="FNanchor_843_843"></a><a class="fnanchor pginternal" href="#Footnote_843_843">[843]</a><br></span>
<span class="i0">That Romeo bid thee fetch?<a id="FNanchor_844_844"></a><a class="fnanchor pginternal" href="#Footnote_844_844">[844]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i>                   Ay, ay, the cords.<a class="fnanchor pginternal" href="#Footnote_844_844">[844]</a><a id="FNanchor_845_845"></a><a class="fnanchor pginternal" href="#Footnote_845_845">[845]</a>       <span class="linenum">35</span><br></span>
</div></div>

<p class="directright">[<i>Throws them down.</i></p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Jul.</i> Ay me! what news? why dost thou wring thy hands?<a id="FNanchor_846_846"></a><a class="fnanchor pginternal" href="#Footnote_846_846">[846]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Ah, well-a-day! he's dead, he's dead, he's dead.<a id="FNanchor_847_847"></a><a class="fnanchor pginternal" href="#Footnote_847_847">[847]</a><br></span>
<span class="i0">We are undone, lady, we are undone.<br></span>
<span class="i0">Alack the day! he's gone, he's kill'd, he's dead.<a id="FNanchor_848_848"></a><a class="fnanchor pginternal" href="#Footnote_848_848">[848]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Can heaven be so envious?<br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i>                         Romeo can,                    <span class="linenum">40</span><br></span>
<span class="i0">Though heaven cannot. O Romeo, Romeo!<br></span>
<span class="i0">Who ever would have thought it? Romeo!<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> What devil art thou that dost torment me thus?<a id="FNanchor_849_849"></a><a class="fnanchor pginternal" href="#Footnote_849_849">[849]</a><br></span>
<span class="i0">This torture should be roar'd in dismal hell.<br></span>
<span class="i0">Hath Romeo slain himself? say thou but 'I,'<a id="FNanchor_850_850"></a><a class="fnanchor pginternal" href="#Footnote_850_850">[850]</a>                    <span class="linenum">45</span><br></span>
<span class="i0">And that bare vowel 'I' shall poison more<a class="fnanchor pginternal" href="#Footnote_850_850">[850]</a><br></span>
<span class="i0">Than the death-darting eye of cockatrice:<a id="FNanchor_851_851"></a><a class="fnanchor pginternal" href="#Footnote_851_851">[851]</a><br></span>
<span class="i0">I am not I, if there be such an I,<a id="FNanchor_852_852"></a><a class="fnanchor pginternal" href="#Footnote_852_852">[852]</a><a id="FNanchor_853_853"></a><a class="fnanchor pginternal" href="#Footnote_853_853">[853]</a><a id="FNanchor_854_854"></a><a class="fnanchor pginternal" href="#Footnote_854_854">[854]</a><a id="FNanchor_855_855"></a><a class="fnanchor pginternal" href="#Footnote_855_855">[855]</a><br></span>
<span class="i0">Or those eyes shut, that make thee answer 'I.'<a class="fnanchor pginternal" href="#Footnote_852_852">[852]</a><a class="fnanchor pginternal" href="#Footnote_853_853">[853]</a><a class="fnanchor pginternal" href="#Footnote_855_855">[855]</a><a id="FNanchor_856_856"></a><a class="fnanchor pginternal" href="#Footnote_856_856">[856]</a><br></span>
<span class="i0">If he be slain, say 'I;' or if not, no:<a class="fnanchor pginternal" href="#Footnote_852_852">[852]</a><a class="fnanchor pginternal" href="#Footnote_855_855">[855]</a>                 <span class="linenum">50</span><br></span>
<span class="i0">Brief sounds determine of my weal or woe.<a class="fnanchor pginternal" href="#Footnote_852_852">[852]</a><a id="FNanchor_857_857"></a><a class="fnanchor pginternal" href="#Footnote_857_857">[857]</a><br></span><span class="pagenum"><a id="Page_75">[Pg 75]</a></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> I saw the wound, I saw it with mine eyes—<br></span>
<span class="i0">God save the mark!—here on his manly breast:<br></span>
<span class="i0">A piteous corse, a bloody piteous corse;<br></span>
<span class="i0">Pale, pale as ashes, all bedaub'd in blood,<a id="FNanchor_858_858"></a><a class="fnanchor pginternal" href="#Footnote_858_858">[858]</a>                    <span class="linenum">55</span><br></span>
<span class="i0">All in gore blood: I swounded at the sight.<a id="FNanchor_859_859"></a><a class="fnanchor pginternal" href="#Footnote_859_859">[859]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O, break, my heart! poor bankrupt, break at once!<a id="FNanchor_860_860"></a><a class="fnanchor pginternal" href="#Footnote_860_860">[860]</a><br></span>
<span class="i0">To prison, eyes, ne'er look on liberty!<br></span>
<span class="i0">Vile earth, to earth resign, end motion here,<a id="FNanchor_861_861"></a><a class="fnanchor pginternal" href="#Footnote_861_861">[861]</a><br></span>
<span class="i0">And thou and Romeo press one heavy bier!<a id="FNanchor_862_862"></a><a class="fnanchor pginternal" href="#Footnote_862_862">[862]</a>                       <span class="linenum">60</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> O Tybalt, Tybalt, the best friend I had!<br></span>
<span class="i0">O courteous Tybalt! honest gentleman!<a id="FNanchor_863_863"></a><a class="fnanchor pginternal" href="#Footnote_863_863">[863]</a><br></span>
<span class="i0">That ever I should live to see thee dead!<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> What storm is this that blows so contrary?<a id="FNanchor_864_864"></a><a class="fnanchor pginternal" href="#Footnote_864_864">[864]</a><br></span>
<span class="i0">Is Romeo slaughter'd, and is Tybalt dead?                           <span class="linenum">65</span><br></span>
<span class="i0">My dear-loved cousin, and my dearer lord?<a id="FNanchor_865_865"></a><a class="fnanchor pginternal" href="#Footnote_865_865">[865]</a><br></span>
<span class="i0">Then, dreadful trumpet, sound the general doom!<a id="FNanchor_866_866"></a><a class="fnanchor pginternal" href="#Footnote_866_866">[866]</a><br></span>
<span class="i0">For who is living, if those two are gone?<br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Tybalt is gone, and Romeo banished:<a id="FNanchor_867_867"></a><a class="fnanchor pginternal" href="#Footnote_867_867">[867]</a><br></span>
<span class="i0">Romeo that kill'd him, he is banished.                              <span class="linenum">70</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O God! did Romeo's hand shed Tybalt's blood?<a id="FNanchor_868_868"></a><a class="fnanchor pginternal" href="#Footnote_868_868">[868]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> It did, it did; alas the day, it did!<a id="FNanchor_869_869"></a><a class="fnanchor pginternal" href="#Footnote_869_869">[869]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O serpent heart, hid with a flowering face!<a id="FNanchor_870_870"></a><a class="fnanchor pginternal" href="#Footnote_870_870">[870]</a><br></span>
<span class="i0">Did ever dragon keep so fair a cave?<a class="fnanchor pginternal" href="#Footnote_870_870">[870]</a><br></span>
<span class="i0">Beautiful tyrant! fiend angelical!                                  <span class="linenum">75</span><br></span><span class="pagenum"><a id="Page_76">[Pg 76]</a></span>
<span class="i0">Dove-feather'd raven! wolvish-ravening lamb!<a id="FNanchor_871_871"></a><a class="fnanchor pginternal" href="#Footnote_871_871">[871]</a><a id="FNanchor_872_872"></a><a class="fnanchor pginternal" href="#Footnote_872_872">[872]</a><br></span>
<span class="i0">Despised substance of divinest show!<a class="fnanchor pginternal" href="#Footnote_872_872">[872]</a><a id="FNanchor_873_873"></a><a class="fnanchor pginternal" href="#Footnote_873_873">[873]</a><a id="FNanchor_874_874"></a><a class="fnanchor pginternal" href="#Footnote_874_874">[874]</a><br></span>
<span class="i0">Just opposite to what thou justly seem'st,<a class="fnanchor pginternal" href="#Footnote_872_872">[872]</a><a class="fnanchor pginternal" href="#Footnote_873_873">[873]</a><br></span>
<span class="i0">A damned saint, an honourable villain!<a class="fnanchor pginternal" href="#Footnote_872_872">[872]</a><a class="fnanchor pginternal" href="#Footnote_873_873">[873]</a><a id="FNanchor_875_875"></a><a class="fnanchor pginternal" href="#Footnote_875_875">[875]</a><br></span>
<span class="i0">O nature, what hadst thou to do in hell,                            <span class="linenum">80</span><br></span>
<span class="i0">When thou didst bower the spirit of a fiend<a id="FNanchor_876_876"></a><a class="fnanchor pginternal" href="#Footnote_876_876">[876]</a><br></span>
<span class="i0">In mortal paradise of such sweet flesh?<br></span>
<span class="i0">Was ever book containing such vile matter<br></span>
<span class="i0">So fairly bound? O, that deceit should dwell<br></span>
<span class="i0">In such a gorgeous palace!<br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i>                   There's no trust,<a id="FNanchor_877_877"></a><a class="fnanchor pginternal" href="#Footnote_877_877">[877]</a>              <span class="linenum">85</span><br></span>
<span class="i0">No faith, no honesty in men; all perjured,<a class="fnanchor pginternal" href="#Footnote_877_877">[877]</a><br></span>
<span class="i0">All forsworn, all naught, all dissemblers.<a class="fnanchor pginternal" href="#Footnote_877_877">[877]</a><a id="FNanchor_878_878"></a><a class="fnanchor pginternal" href="#Footnote_878_878">[878]</a><br></span>
<span class="i0">Ah, where's my man? give me some aqua vitæ:<br></span>
<span class="i0">These griefs, these woes, these sorrows make me old.<br></span>
<span class="i0">Shame come to Romeo!<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i>               Blister'd be thy tongue<a id="FNanchor_879_879"></a><a class="fnanchor pginternal" href="#Footnote_879_879">[879]</a>              <span class="linenum">90</span><br></span>
<span class="i0">For such a wish! he was not born to shame:<br></span>
<span class="i0">Upon his brow shame is ashamed to sit;<br></span>
<span class="i0">For 'tis a throne where honour may be crown'd<br></span>
<span class="i0">Sole monarch of the universal earth.<br></span>
<span class="i0">O, what a beast was I to chide at him!<a id="FNanchor_880_880"></a><a class="fnanchor pginternal" href="#Footnote_880_880">[880]</a>                         <span class="linenum">95</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Will you speak well of him that kill'd your cousin?<a id="FNanchor_881_881"></a><a class="fnanchor pginternal" href="#Footnote_881_881">[881]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Shall I speak ill of him that is my husband?<br></span>
<span class="i0">Ah, poor my lord, what tongue shall smooth thy name,<br></span><span class="pagenum"><a id="Page_77">[Pg 77]</a></span>
<span class="i0">When I, thy three-hours wife, have mangled it?<br></span>
<span class="i0">But wherefore, villain, didst thou kill my cousin?                 <span class="linenum">100</span><br></span>
<span class="i0">That villain cousin would have kill'd my husband:<br></span>
<span class="i0">Back, foolish tears, back to your native spring;<br></span>
<span class="i0">Your tributary drops belong to woe,<br></span>
<span class="i0">Which you mistaking offer up to joy.<a id="FNanchor_882_882"></a><a class="fnanchor pginternal" href="#Footnote_882_882">[882]</a><br></span>
<span class="i0">My husband lives, that Tybalt would have slain;                    <span class="linenum">105</span><br></span>
<span class="i0">And Tybalt's dead, that would have slain my husband:<a id="FNanchor_883_883"></a><a class="fnanchor pginternal" href="#Footnote_883_883">[883]</a><br></span>
<span class="i0">All this is comfort; wherefore weep I then?<br></span>
<span class="i0">Some word there was, worser than Tybalt's death,<a id="FNanchor_884_884"></a><a class="fnanchor pginternal" href="#Footnote_884_884">[884]</a><br></span>
<span class="i0">That murder'd me: I would forget it fain;<a id="FNanchor_885_885"></a><a class="fnanchor pginternal" href="#Footnote_885_885">[885]</a><br></span>
<span class="i0">But, O, it presses to my memory,                                   <span class="linenum">110</span><br></span>
<span class="i0">Like damned guilty deeds to sinners' minds:<br></span>
<span class="i0">'Tybalt is dead, and Romeo banished;'<br></span>
<span class="i0">That 'banished,' that one word 'banished,'<br></span>
<span class="i0">Hath slain ten thousand Tybalts. Tybalt's death<br></span>
<span class="i0">Was woe enough, if it had ended there:                             <span class="linenum">115</span><br></span>
<span class="i0">Or, if sour woe delights in fellowship<br></span>
<span class="i0">And needly will be rank'd with other griefs,<a id="FNanchor_886_886"></a><a class="fnanchor pginternal" href="#Footnote_886_886">[886]</a><br></span>
<span class="i0">Why follow'd not, when she said 'Tybalt's dead,'<a id="FNanchor_887_887"></a><a class="fnanchor pginternal" href="#Footnote_887_887">[887]</a><br></span>
<span class="i0">Thy father, or thy mother, nay, or both,<br></span>
<span class="i0">Which modern lamentation might have moved?<a id="FNanchor_888_888"></a><a class="fnanchor pginternal" href="#Footnote_888_888">[888]</a>                    <span class="linenum">120</span><br></span>
<span class="i0">But with a rear-ward following Tybalt's death,<a id="FNanchor_889_889"></a><a class="fnanchor pginternal" href="#Footnote_889_889">[889]</a><br></span>
<span class="i0">'Romeo is banished:' to speak that word,<a id="FNanchor_890_890"></a><a class="fnanchor pginternal" href="#Footnote_890_890">[890]</a><br></span>
<span class="i0">Is father, mother, Tybalt, Romeo, Juliet,<br></span>
<span class="i0">All slain, all dead. 'Romeo is banished.'<br></span>
<span class="i0">There is no end, no limit, measure, bound,                         <span class="linenum">125</span><br></span>
<span class="i0">In that word's death; no words can that woe sound.<br></span>
<span class="i0">Where is my father, and my mother, nurse?<br></span>
<span class="pagenum"><a id="Page_78">[Pg 78]</a></span></div><div class="stanza">
<span class="i0"><i>Nurse.</i> Weeping and wailing over Tybalt's corse:<a id="FNanchor_891_891"></a><a class="fnanchor pginternal" href="#Footnote_891_891">[891]</a><br></span>
<span class="i0">Will you go to them? I will bring you thither.<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Wash they his wounds with tears: mine shall be spent,<a id="FNanchor_892_892"></a><a class="fnanchor pginternal" href="#Footnote_892_892">[892]</a><span class="linenum">130</span><br></span>
<span class="i0">When theirs are dry, for Romeo's banishment.<br></span>
<span class="i0">Take up those cords: poor ropes, you are beguiled,<a id="FNanchor_893_893"></a><a class="fnanchor pginternal" href="#Footnote_893_893">[893]</a><a id="FNanchor_894_894"></a><a class="fnanchor pginternal" href="#Footnote_894_894">[894]</a><br></span>
<span class="i0">Both you and I; for Romeo is exiled:<a class="fnanchor pginternal" href="#Footnote_893_893">[893]</a><a id="FNanchor_895_895"></a><a class="fnanchor pginternal" href="#Footnote_895_895">[895]</a><br></span>
<span class="i0">He made you for a highway to my bed;<a class="fnanchor pginternal" href="#Footnote_893_893">[893]</a><a id="FNanchor_896_896"></a><a class="fnanchor pginternal" href="#Footnote_896_896">[896]</a><br></span>
<span class="i0">But I, a maid, die maiden-widowed.<a class="fnanchor pginternal" href="#Footnote_893_893">[893]</a><a id="FNanchor_897_897"></a><a class="fnanchor pginternal" href="#Footnote_897_897">[897]</a>                      <span class="linenum">135</span><br></span>
<span class="i0">Come, cords; come, nurse; I'll to my wedding-bed;<a class="fnanchor pginternal" href="#Footnote_893_893">[893]</a><a id="FNanchor_898_898"></a><a class="fnanchor pginternal" href="#Footnote_898_898">[898]</a><br></span>
<span class="i0">And death, not Romeo, take my maidenhead!<a class="fnanchor pginternal" href="#Footnote_893_893">[893]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Hie to your chamber: I'll find Romeo<br></span>
<span class="i0">To comfort you: I wot well where he is.<br></span>
<span class="i0">Hark ye, your Romeo will be here at night:<a id="FNanchor_899_899"></a><a class="fnanchor pginternal" href="#Footnote_899_899">[899]</a>                    <span class="linenum">140</span><br></span>
<span class="i0">I'll to him; he is hid at Laurence' cell.<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O, find him! give this ring to my true knight,<br></span>
<span class="i0">And bid him come to take his last farewell.<a id="FNanchor_900_900"></a><a class="fnanchor pginternal" href="#Footnote_900_900">[900]</a>      <span class="directline">[<i>Exeunt.</i><br></span></span>
</div></div>


<h3><span class="smcap">Scene III.</span> <i>Friar Laurence's cell.</i><a id="FNanchor_901_901"></a><a class="fnanchor pginternal" href="#Footnote_901_901">[901]</a></h3>

<p class="directcenter"><i>Enter</i> <span class="smcap">Friar Laurence</span>.<a id="FNanchor_902_902"></a><a class="fnanchor pginternal" href="#Footnote_902_902">[902]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Fri. L.</i> Romeo, come forth; come forth, thou fearful man:<a id="FNanchor_903_903"></a><a class="fnanchor pginternal" href="#Footnote_903_903">[903]</a><br></span>
<span class="i0">Affliction is enamour'd of thy parts,<a id="FNanchor_904_904"></a><a class="fnanchor pginternal" href="#Footnote_904_904">[904]</a><br></span>
<span class="i0">And thou art wedded to calamity.<br></span>
</div></div>

<p><span class="pagenum"><a id="Page_79">[Pg 79]</a></span></p>

<p class="directcenter"><i>Enter</i> <span class="smcap">Romeo</span>.<a id="FNanchor_905_905"></a><a class="fnanchor pginternal" href="#Footnote_905_905">[905]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Rom.</i> Father, what news? what is the prince's doom?<a id="FNanchor_906_906"></a><a class="fnanchor pginternal" href="#Footnote_906_906">[906]</a><br></span>
<span class="i0">What sorrow craves acquaintance at my hand,<a id="FNanchor_907_907"></a><a class="fnanchor pginternal" href="#Footnote_907_907">[907]</a>                     <span class="linenum">5</span><br></span>
<span class="i0">That I yet know not?<br></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i>            Too familiar<br></span>
<span class="i0">Is my dear son with such sour company:<a id="FNanchor_908_908"></a><a class="fnanchor pginternal" href="#Footnote_908_908">[908]</a><br></span>
<span class="i0">I bring thee tidings of the prince's doom.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> What less than dooms-day is the prince's doom?<a id="FNanchor_909_909"></a><a class="fnanchor pginternal" href="#Footnote_909_909">[909]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i> A gentler judgement vanish'd from his lips,<a id="FNanchor_910_910"></a><a class="fnanchor pginternal" href="#Footnote_910_910">[910]</a>     <span class="linenum">10</span><br></span>
<span class="i0">Not body's death, but body's banishment.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Ha, banishment! be merciful, say 'death;'<br></span>
<span class="i0">For exile hath more terror in his look,<br></span>
<span class="i0">Much more than death: do not say 'banishment.'<a id="FNanchor_911_911"></a><a class="fnanchor pginternal" href="#Footnote_911_911">[911]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i> Here from Verona art thou banished:<a id="FNanchor_912_912"></a><a class="fnanchor pginternal" href="#Footnote_912_912">[912]</a>             <span class="linenum">15</span><br></span>
<span class="i0">Be patient, for the world is broad and wide.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> There is no world without Verona walls,<a id="FNanchor_913_913"></a><a class="fnanchor pginternal" href="#Footnote_913_913">[913]</a><br></span>
<span class="i0">But purgatory, torture, hell itself.<a id="FNanchor_914_914"></a><a class="fnanchor pginternal" href="#Footnote_914_914">[914]</a><br></span>
<span class="i0">Hence banished is banish'd from the world,<a id="FNanchor_915_915"></a><a class="fnanchor pginternal" href="#Footnote_915_915">[915]</a><br></span>
<span class="i0">And world's exile is death: then 'banished'<a id="FNanchor_916_916"></a><a class="fnanchor pginternal" href="#Footnote_916_916">[916]</a><a id="FNanchor_917_917"></a><a class="fnanchor pginternal" href="#Footnote_917_917">[917]</a><a id="FNanchor_918_918"></a><a class="fnanchor pginternal" href="#Footnote_918_918">[918]</a>          <span class="linenum">20</span><br></span>
<span class="i0">Is death mis-term'd: calling death 'banished,'<a class="fnanchor pginternal" href="#Footnote_917_917">[917]</a><a id="FNanchor_919_919"></a><a class="fnanchor pginternal" href="#Footnote_919_919">[919]</a><br></span>
<span class="i0">Thou cut'st my head off with a golden axe<br></span>
<span class="i0">And smilest upon the stroke that murders me.<a id="FNanchor_920_920"></a><a class="fnanchor pginternal" href="#Footnote_920_920">[920]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i> O deadly sin! O rude unthankfulness!<br></span>
<span class="i0">Thy fault our law calls death; but the kind prince,                 <span class="linenum">25</span><br></span>
<span class="i0">Taking thy part, hath rush'd aside the law,<a id="FNanchor_921_921"></a><a class="fnanchor pginternal" href="#Footnote_921_921">[921]</a><br></span>
<span class="i0">And turn'd that black word death to banishment:<br></span><span class="pagenum"><a id="Page_80">[Pg 80]</a></span>
<span class="i0">This is dear mercy, and thou seest it not.<a id="FNanchor_922_922"></a><a class="fnanchor pginternal" href="#Footnote_922_922">[922]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> 'Tis torture, and not mercy: heaven is here,<br></span>
<span class="i0">Where Juliet lives; and every cat and dog                           <span class="linenum">30</span><br></span>
<span class="i0">And little mouse, every unworthy thing,<br></span>
<span class="i0">Live here in heaven and may look on her,<a id="FNanchor_923_923"></a><a class="fnanchor pginternal" href="#Footnote_923_923">[923]</a><br></span>
<span class="i0">But Romeo may not: more validity,<br></span>
<span class="i0">More honourable state, more courtship lives<br></span>
<span class="i0">In carrion-flies than Romeo: they may seize                         <span class="linenum">35</span><br></span>
<span class="i0">On the white wonder of dear Juliet's hand,<br></span>
<span class="i0">And steal immortal blessing from her lips;<a id="FNanchor_924_924"></a><a class="fnanchor pginternal" href="#Footnote_924_924">[924]</a><br></span>
<span class="i0">Who, even in pure and vestal modesty,<a id="FNanchor_925_925"></a><a class="fnanchor pginternal" href="#Footnote_925_925">[925]</a><a id="FNanchor_926_926"></a><a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><br></span>
<span class="i0">Still blush, as thinking their own kisses sin;<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><a id="FNanchor_927_927"></a><a class="fnanchor pginternal" href="#Footnote_927_927">[927]</a><br></span>
<span class="i0">But Romeo may not; he is banished:<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><a id="FNanchor_928_928"></a><a class="fnanchor pginternal" href="#Footnote_928_928">[928]</a>                       <span class="linenum">40</span><br></span>
<span class="i0">This may flies do, but I from this must fly:<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><a class="fnanchor pginternal" href="#Footnote_928_928">[928]</a><br></span>
<span class="i0">They are free men, but I am banished:<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><a class="fnanchor pginternal" href="#Footnote_928_928">[928]</a><br></span>
<span class="i0">And say'st thou yet, that exile is not death?<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><a class="fnanchor pginternal" href="#Footnote_928_928">[928]</a><br></span>
<span class="i0">Hadst thou no poison mix'd, no sharp-ground knife,<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><a id="FNanchor_929_929"></a><a class="fnanchor pginternal" href="#Footnote_929_929">[929]</a><br></span>
<span class="i0">No sudden mean of death, though ne'er so mean,<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a>                <span class="linenum">45</span><br></span>
<span class="i0">But 'banished' to kill me?—'Banished'?<a class="fnanchor pginternal" href="#Footnote_926_926">[926]</a><br></span>
<span class="i0">O friar, the damned use that word in hell;<br></span>
<span class="i0">Howling attends it: how hast thou the heart,<a id="FNanchor_930_930"></a><a class="fnanchor pginternal" href="#Footnote_930_930">[930]</a><br></span>
<span class="i0">Being a divine, a ghostly confessor,<br></span>
<span class="i0">A sin-absolver, and my friend profess'd,<a id="FNanchor_931_931"></a><a class="fnanchor pginternal" href="#Footnote_931_931">[931]</a>                       <span class="linenum">50</span><br></span>
<span class="i0">To mangle me with that word 'banished'?<a id="FNanchor_932_932"></a><a class="fnanchor pginternal" href="#Footnote_932_932">[932]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i> Thou fond mad man, hear me but speak a word.<a id="FNanchor_933_933"></a><a class="fnanchor pginternal" href="#Footnote_933_933">[933]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> O, thou wilt speak again of banishment.<br></span>
<span class="pagenum"><a id="Page_81">[Pg 81]</a></span></div><div class="stanza">
<span class="i0"><i>Fri. L.</i> I'll give thee armour to keep off that word;<a id="FNanchor_934_934"></a><a class="fnanchor pginternal" href="#Footnote_934_934">[934]</a><br></span>
<span class="i0">Adversity's sweet milk, philosophy,                                 <span class="linenum">55</span><br></span>
<span class="i0">To comfort thee, though thou art banished.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Yet 'banished'? Hang up philosophy!<br></span>
<span class="i0">Unless philosophy can make a Juliet,<br></span>
<span class="i0">Displant a town, reverse a prince's doom,<br></span>
<span class="i0">It helps not, it prevails not: talk no more.<a id="FNanchor_935_935"></a><a class="fnanchor pginternal" href="#Footnote_935_935">[935]</a>                   <span class="linenum">60</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Fr. L.</i> O, then I see that madmen have no ears.<a id="FNanchor_936_936"></a><a class="fnanchor pginternal" href="#Footnote_936_936">[936]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> How should they, when that wise men have no eyes?<a id="FNanchor_937_937"></a><a class="fnanchor pginternal" href="#Footnote_937_937">[937]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Fr. L.</i> Let me dispute with thee of thy estate.<a id="FNanchor_938_938"></a><a class="fnanchor pginternal" href="#Footnote_938_938">[938]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Thou canst not speak of that thou dost not feel:<a id="FNanchor_939_939"></a><a class="fnanchor pginternal" href="#Footnote_939_939">[939]</a><br></span>
<span class="i0">Wert thou as young as I, Juliet thy love,<a id="FNanchor_940_940"></a><a class="fnanchor pginternal" href="#Footnote_940_940">[940]</a>                      <span class="linenum">65</span><br></span>
<span class="i0">An hour but married, Tybalt murdered,<a id="FNanchor_941_941"></a><a class="fnanchor pginternal" href="#Footnote_941_941">[941]</a><br></span>
<span class="i0">Doting like me, and like me banished,<br></span>
<span class="i0">Then mightst thou speak, then mightst thou tear thy hair,<a id="FNanchor_942_942"></a><a class="fnanchor pginternal" href="#Footnote_942_942">[942]</a><br></span>
<span class="i0">And fall upon the ground, as I do now,<br></span>
<span class="i0">Taking the measure of an unmade grave.<a id="FNanchor_943_943"></a><a class="fnanchor pginternal" href="#Footnote_943_943">[943]</a>       <span class="directline">[<i>Knocking within.</i><span class="linenum">70</span><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i> Arise; one knocks; good Romeo, hide thyself.<a id="FNanchor_944_944"></a><a class="fnanchor pginternal" href="#Footnote_944_944">[944]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Not I; unless the breath of heart-sick groans<a id="FNanchor_945_945"></a><a class="fnanchor pginternal" href="#Footnote_945_945">[945]</a><a id="FNanchor_946_946"></a><a class="fnanchor pginternal" href="#Footnote_946_946">[946]</a><br></span>
<span class="i0">Mist-like infold me from the search of eyes.<a class="fnanchor pginternal" href="#Footnote_945_945">[945]</a><a id="FNanchor_947_947"></a><a class="fnanchor pginternal" href="#Footnote_947_947">[947]</a>      <span class="directline">[<i>Knocking.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i> Hark, how they knock! Who's there? Romeo, arise;<a class="fnanchor pginternal" href="#Footnote_945_945">[945]</a><a id="FNanchor_948_948"></a><a class="fnanchor pginternal" href="#Footnote_948_948">[948]</a><br></span>
<span class="i0">Thou wilt be taken.—Stay awhile!—Stand up;<a id="FNanchor_949_949"></a><a class="fnanchor pginternal" href="#Footnote_949_949">[949]</a>      <span class="directline">[<i>Knocking.</i><span class="linenum">75</span><br></span><span class="pagenum"><a id="Page_82">[Pg 82]</a></span></span>
<span class="i0">Run to my study.—By and by! God's will,<br></span>
<span class="i0">What simpleness is this!—I come, I come!<a id="FNanchor_950_950"></a><a class="fnanchor pginternal" href="#Footnote_950_950">[950]</a>      <span class="directline">[<i>Knocking.</i><br></span></span>
<span class="i0">Who knocks so hard? whence come you? what's your will?<a id="FNanchor_951_951"></a><a class="fnanchor pginternal" href="#Footnote_951_951">[951]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> [<i>Within</i>] Let me come in, and you shall know my errand;<a id="FNanchor_952_952"></a><a class="fnanchor pginternal" href="#Footnote_952_952">[952]</a><br></span>
<span class="i0">I come from Lady Juliet.<br></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i>                Welcome, then.<a id="FNanchor_953_953"></a><a class="fnanchor pginternal" href="#Footnote_953_953">[953]</a>                   <span class="linenum">80</span><br></span>
</div></div>

<p class="directcenter"><i>Enter</i> Nurse.
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Nurse.</i> O holy friar, O, tell me, holy friar,<br></span>
<span class="i0">Where is my lady's lord, where's Romeo?<a id="FNanchor_954_954"></a><a class="fnanchor pginternal" href="#Footnote_954_954">[954]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i> There on the ground, with his own tears made drunk.<a id="FNanchor_955_955"></a><a class="fnanchor pginternal" href="#Footnote_955_955">[955]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> O, he is even in my mistress' case,<a id="FNanchor_956_956"></a><a class="fnanchor pginternal" href="#Footnote_956_956">[956]</a><br></span>
<span class="i0">Just in her case!<br></span>
</div><div class="stanza">
<span class="i0"><i>Fr. L.</i>          O woeful sympathy!<a id="FNanchor_957_957"></a><a class="fnanchor pginternal" href="#Footnote_957_957">[957]</a>                      <span class="linenum">85</span><br></span>
<span class="i0">Piteous predicament!<a class="fnanchor pginternal" href="#Footnote_957_957">[957]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i>             Even so lies she,<a id="FNanchor_958_958"></a><a class="fnanchor pginternal" href="#Footnote_958_958">[958]</a><br></span>
<span class="i0">Blubbering and weeping, weeping and blubbering.<br></span>
<span class="i0">Stand up, stand up; stand, an you be a man:<a id="FNanchor_959_959"></a><a class="fnanchor pginternal" href="#Footnote_959_959">[959]</a><a id="FNanchor_960_960"></a><a class="fnanchor pginternal" href="#Footnote_960_960">[960]</a><br></span>
<span class="i0">For Juliet's sake, for her sake, rise and stand;<a class="fnanchor pginternal" href="#Footnote_959_959">[959]</a><br></span>
<span class="i0">Why should you fall into so deep an O?<a id="FNanchor_961_961"></a><a class="fnanchor pginternal" href="#Footnote_961_961">[961]</a>                         <span class="linenum">90</span><br></span>
<span class="pagenum"><a id="Page_83">[Pg 83]</a></span></div><div class="stanza">
<span class="i0"><i>Rom.</i> Nurse!<a class="fnanchor pginternal" href="#Footnote_961_961">[961]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Ah sir! ah sir! Well, death's the end of all.<a id="FNanchor_962_962"></a><a class="fnanchor pginternal" href="#Footnote_962_962">[962]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Spakest thou of Juliet? how is it with her?<a id="FNanchor_963_963"></a><a class="fnanchor pginternal" href="#Footnote_963_963">[963]</a><br></span>
<span class="i0">Doth she not think me an old murderer,<a id="FNanchor_964_964"></a><a class="fnanchor pginternal" href="#Footnote_964_964">[964]</a><br></span>
<span class="i0">Now I have stain'd the childhood of our joy<a id="FNanchor_965_965"></a><a class="fnanchor pginternal" href="#Footnote_965_965">[965]</a>                    <span class="linenum">95</span><br></span>
<span class="i0">With blood removed but little from her own?<br></span>
<span class="i0">Where is she? and how doth she? and what says<a id="FNanchor_966_966"></a><a class="fnanchor pginternal" href="#Footnote_966_966">[966]</a><br></span>
<span class="i0">My conceal'd lady to our cancell'd love?<a id="FNanchor_967_967"></a><a class="fnanchor pginternal" href="#Footnote_967_967">[967]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> O, she says nothing, sir, but weeps and weeps;<br></span>
<span class="i0">And now falls on her bed; and then starts up,                      <span class="linenum">100</span><br></span>
<span class="i0">And Tybalt calls; and then on Romeo cries,<a id="FNanchor_968_968"></a><a class="fnanchor pginternal" href="#Footnote_968_968">[968]</a><br></span>
<span class="i0">And then down falls again.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i>                     As if that name,<a id="FNanchor_969_969"></a><a class="fnanchor pginternal" href="#Footnote_969_969">[969]</a><br></span>
<span class="i0">Shot from the deadly level of a gun,<a class="fnanchor pginternal" href="#Footnote_969_969">[969]</a><a id="FNanchor_970_970"></a><a class="fnanchor pginternal" href="#Footnote_970_970">[970]</a><br></span>
<span class="i0">Did murder her; as that name's cursed hand<br></span>
<span class="i0">Murder'd her kinsman. O, tell me, friar, tell me,<a id="FNanchor_971_971"></a><a class="fnanchor pginternal" href="#Footnote_971_971">[971]</a>             <span class="linenum">105</span><br></span>
<span class="i0">In what vile part of this anatomy<a id="FNanchor_972_972"></a><a class="fnanchor pginternal" href="#Footnote_972_972">[972]</a><br></span>
<span class="i0">Doth my name lodge? tell me, that I may sack<br></span>
<span class="i0">The hateful mansion.<a id="FNanchor_973_973"></a><a class="fnanchor pginternal" href="#Footnote_973_973">[973]</a>       <span class="directline">[<i>Drawing his sword.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Fri. L.</i>            Hold thy desperate hand:<br></span>
<span class="i0">Art thou a man? thy form cries out thou art:<br></span>
<span class="i0">Thy tears are womanish; thy wild acts denote<a id="FNanchor_974_974"></a><a class="fnanchor pginternal" href="#Footnote_974_974">[974]</a>                  <span class="linenum">110</span><br></span>
<span class="i0">The unreasonable fury of a beast:<br></span>
<span class="i0">Unseemly woman in a seeming man!<a id="FNanchor_975_975"></a><a class="fnanchor pginternal" href="#Footnote_975_975">[975]</a><br></span>
<span class="i0">Or ill-beseeming beast in seeming both!<a class="fnanchor pginternal" href="#Footnote_975_975">[975]</a><a id="FNanchor_976_976"></a><a class="fnanchor pginternal" href="#Footnote_976_976">[976]</a><br></span><span class="pagenum"><a id="Page_84">[Pg 84]</a></span>
<span class="i0">Thou hast amazed me: by my holy order,<br></span>
<span class="i0">I thought thy disposition better temper'd.                         <span class="linenum">115</span><br></span>
<span class="i0">Hast thou slain Tybalt? wilt thou slay thyself?<br></span>
<span class="i0">And slay thy lady that in thy life lives,<a id="FNanchor_977_977"></a><a class="fnanchor pginternal" href="#Footnote_977_977">[977]</a><br></span>
<span class="i0">By doing damned hate upon thyself?<a id="FNanchor_978_978"></a><a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">Why rail'st thou on thy birth, the heaven and earth?<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><a id="FNanchor_979_979"></a><a class="fnanchor pginternal" href="#Footnote_979_979">[979]</a><br></span>
<span class="i0">Since birth and heaven and earth, all three do meet<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><a id="FNanchor_980_980"></a><a class="fnanchor pginternal" href="#Footnote_980_980">[980]</a>     <span class="linenum">120</span><br></span>
<span class="i0">In thee at once, which thou at once wouldst lose.<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><a class="fnanchor pginternal" href="#Footnote_120_120">[120]</a><a id="FNanchor_981_981"></a><a class="fnanchor pginternal" href="#Footnote_981_981">[981]</a><br></span>
<span class="i0">Fie, fie, thou shamest thy shape, thy love, thy wit;<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">Which, like a usurer, abound'st in all,<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><a id="FNanchor_982_982"></a><a class="fnanchor pginternal" href="#Footnote_982_982">[982]</a><br></span>
<span class="i0">And usest none in that true use indeed<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">Which should bedeck thy shape, thy love, thy wit:<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a>            <span class="linenum">125</span><br></span>
<span class="i0">Thy noble shape is but a form of wax,<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">Digressing from the valour of a man;<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><a id="FNanchor_983_983"></a><a class="fnanchor pginternal" href="#Footnote_983_983">[983]</a><br></span>
<span class="i0">Thy dear love sworn, but hollow perjury,<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">Killing that love which thou hast vow'd to cherish;<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">Thy wit, that ornament to shape and love,<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a>                    <span class="linenum">130</span><br></span>
<span class="i0">Mis-shapen in the conduct of them both,<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">Like powder in a skilless soldier's flask,<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><a id="FNanchor_984_984"></a><a class="fnanchor pginternal" href="#Footnote_984_984">[984]</a><br></span>
<span class="i0">Is set a-fire by thine own ignorance,<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><a id="FNanchor_985_985"></a><a class="fnanchor pginternal" href="#Footnote_985_985">[985]</a><br></span>
<span class="i0">And thou dismember'd with thine own defence.<a class="fnanchor pginternal" href="#Footnote_978_978">[978]</a><br></span>
<span class="i0">What, rouse thee, man! thy Juliet is alive,                        <span class="linenum">135</span><br></span>
<span class="i0">For whose dear sake thou wast but lately dead;<br></span>
<span class="i0">There art thou happy: Tybalt would kill thee,<br></span>
<span class="i0">But thou slew'st Tybalt; there art thou happy too:<a id="FNanchor_986_986"></a><a class="fnanchor pginternal" href="#Footnote_986_986">[986]</a><br></span>
<span class="i0">The law, that threaten'd death, becomes thy friend,<a id="FNanchor_987_987"></a><a class="fnanchor pginternal" href="#Footnote_987_987">[987]</a><br></span>
<span class="i0">And turns it to exile; there art thou happy:<a id="FNanchor_988_988"></a><a class="fnanchor pginternal" href="#Footnote_988_988">[988]</a>                  <span class="linenum">140</span><br></span>
<span class="i0">A pack of blessings lights upon thy back;<a id="FNanchor_989_989"></a><a class="fnanchor pginternal" href="#Footnote_989_989">[989]</a><br></span><span class="pagenum"><a id="Page_85">[Pg 85]</a></span>
<span class="i0">Happiness courts thee in her best array;<br></span>
<span class="i0">But, like a misbehaved and sullen wench,<a id="FNanchor_990_990"></a><a class="fnanchor pginternal" href="#Footnote_990_990">[990]</a><br></span>
<span class="i0">Thou pout'st upon thy fortune and thy love:<a id="FNanchor_991_991"></a><a class="fnanchor pginternal" href="#Footnote_991_991">[991]</a><br></span>
<span class="i0">Take heed, take heed, for such die miserable.                      <span class="linenum">145</span><br></span>
<span class="i0">Go, get thee to thy love, as was decreed,<br></span>
<span class="i0">Ascend her chamber, hence and comfort her:<br></span>
<span class="i0">But look thou stay not till the watch be set,<br></span>
<span class="i0">For then thou canst not pass to Mantua;<br></span>
<span class="i0">Where thou shalt live till we can find a time                      <span class="linenum">150</span><br></span>
<span class="i0">To blaze your marriage, reconcile your friends,<br></span>
<span class="i0">Beg pardon of the prince and call thee back<a id="FNanchor_992_992"></a><a class="fnanchor pginternal" href="#Footnote_992_992">[992]</a><br></span>
<span class="i0">With twenty hundred thousand times more joy<br></span>
<span class="i0">Than thou went'st forth in lamentation.<br></span>
<span class="i0">Go before, nurse: commend me to thy lady,                          <span class="linenum">155</span><br></span>
<span class="i0">And bid her hasten all the house to bed,<br></span>
<span class="i0">Which heavy sorrow makes them apt unto:<br></span>
<span class="i0">Romeo is coming.<br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> O Lord, I could have stay'd here all the night<a id="FNanchor_993_993"></a><a class="fnanchor pginternal" href="#Footnote_993_993">[993]</a><br></span>
<span class="i0">To hear good counsel: O, what learning is!<a id="FNanchor_994_994"></a><a class="fnanchor pginternal" href="#Footnote_994_994">[994]</a>                    <span class="linenum">160</span><br></span>
<span class="i0">My lord, I'll tell my lady you will come.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Do so, and bid my sweet prepare to chide.<br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Here, sir, a ring she bid me give you, sir:<a id="FNanchor_995_995"></a><a class="fnanchor pginternal" href="#Footnote_995_995">[995]</a><br></span>
<span class="i0">Hie you, make haste, for it grows very late.<a id="FNanchor_996_996"></a><a class="fnanchor pginternal" href="#Footnote_996_996">[996]</a>      <span class="directline">[<i>Exit.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> How well my comfort is revived by this!                <span class="linenum">165</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Fri.</i> Go hence; good night; and here stands all your state:<a id="FNanchor_997_997"></a><a class="fnanchor pginternal" href="#Footnote_997_997">[997]</a><a id="FNanchor_998_998"></a><a class="fnanchor pginternal" href="#Footnote_998_998">[998]</a><br></span>
<span class="i0">Either be gone before the watch be set,<a class="fnanchor pginternal" href="#Footnote_997_997">[997]</a><br></span><span class="pagenum"><a id="Page_86">[Pg 86]</a></span>
<span class="i0">Or by the break of day disguised from hence:<a class="fnanchor pginternal" href="#Footnote_997_997">[997]</a><a id="FNanchor_999_999"></a><a class="fnanchor pginternal" href="#Footnote_999_999">[999]</a><br></span>
<span class="i0">Sojourn in Mantua; I'll find out your man,<br></span>
<span class="i0">And he shall signify from time to time                             <span class="linenum">170</span><br></span>
<span class="i0">Every good hap to you that chances here:<br></span>
<span class="i0">Give me thy hand; 'tis late: farewell; good night.<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> But that a joy past joy calls out on me,<br></span>
<span class="i0">It were a grief, so brief to part with thee:<br></span>
<span class="i0">Farewell.<a id="FNanchor_1000_1000"></a><a class="fnanchor pginternal" href="#Footnote_1000_1000">[1000]</a>                 <span class="directline">[<i>Exeunt.</i>                    <span class="linenum">175</span><br></span></span>
</div></div>


<h3><span class="smcap">Scene IV.</span> <i>A room in Capulet's house.</i><a id="FNanchor_1001_1001"></a><a class="fnanchor pginternal" href="#Footnote_1001_1001">[1001]</a></h3>

<p class="directcenter"><i>Enter</i> <span class="smcap">Capulet, Lady Capulet</span>, <i>and</i> <span class="smcap">Paris</span>.<a id="FNanchor_1002_1002"></a><a class="fnanchor pginternal" href="#Footnote_1002_1002">[1002]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Cap.</i> Things have fall'n out, sir, so unluckily<br></span>
<span class="i0">That we have had no time to move our daughter.<a id="FNanchor_1003_1003"></a><a class="fnanchor pginternal" href="#Footnote_1003_1003">[1003]</a><br></span>
<span class="i0">Look you, she loved her kinsman Tybalt dearly,<br></span>
<span class="i0">And so did I. Well, we were born to die.<br></span>
<span class="i0">'Tis very late; she'll not come down to-night:                       <span class="linenum">5</span><br></span>
<span class="i0">I promise you, but for your company,<a id="FNanchor_1004_1004"></a><a class="fnanchor pginternal" href="#Footnote_1004_1004">[1004]</a><br></span>
<span class="i0">I would have been a-bed an hour ago.<a class="fnanchor pginternal" href="#Footnote_1004_1004">[1004]</a><a id="FNanchor_1005_1005"></a><a class="fnanchor pginternal" href="#Footnote_1005_1005">[1005]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Par.</i> These times of woe afford no time to woo.<a id="FNanchor_1006_1006"></a><a class="fnanchor pginternal" href="#Footnote_1006_1006">[1006]</a><br></span>
<span class="i0">Madam, good night: commend me to your daughter.<br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> I will, and know her mind early to-morrow;<a id="FNanchor_1007_1007"></a><a class="fnanchor pginternal" href="#Footnote_1007_1007">[1007]</a>    <span class="linenum">10</span><br></span>
<span class="i0">To-night she's mew'd up to her heaviness.<a class="fnanchor pginternal" href="#Footnote_1007_1007">[1007]</a><a id="FNanchor_1008_1008"></a><a class="fnanchor pginternal" href="#Footnote_1008_1008">[1008]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i> Sir Paris, I will make a desperate tender<a id="FNanchor_1009_1009"></a><a class="fnanchor pginternal" href="#Footnote_1009_1009">[1009]</a><br></span>
<span class="i0">Of my child's love: I think she will be ruled<a id="FNanchor_1010_1010"></a><a class="fnanchor pginternal" href="#Footnote_1010_1010">[1010]</a><br></span>
<span class="i0">In all respects by me; nay more, I doubt it not.<a id="FNanchor_1011_1011"></a><a class="fnanchor pginternal" href="#Footnote_1011_1011">[1011]</a><br></span><span class="pagenum"><a id="Page_87">[Pg 87]</a></span>
<span class="i0">Wife, go you to her ere you go to bed;                              <span class="linenum">15</span><br></span>
<span class="i0">Acquaint her here of my son Paris' love;<a id="FNanchor_1012_1012"></a><a class="fnanchor pginternal" href="#Footnote_1012_1012">[1012]</a><br></span>
<span class="i0">And bid her, mark you me, on Wednesday next—<a id="FNanchor_1013_1013"></a><a class="fnanchor pginternal" href="#Footnote_1013_1013">[1013]</a><a id="FNanchor_1014_1014"></a><a class="fnanchor pginternal" href="#Footnote_1014_1014">[1014]</a><br></span>
<span class="i0">But, soft! what day is this?<br></span>
</div><div class="stanza">
<span class="i0"><i>Par.</i>                       Monday, my lord.<br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i> Monday! ha, ha! Well, Wednesday is too soon;<a class="fnanchor pginternal" href="#Footnote_1014_1014">[1014]</a><br></span>
<span class="i0">O' Thursday let it be: o' Thursday, tell her,<a id="FNanchor_1015_1015"></a><a class="fnanchor pginternal" href="#Footnote_1015_1015">[1015]</a><a id="FNanchor_1016_1016"></a><a class="fnanchor pginternal" href="#Footnote_1016_1016">[1016]</a>           <span class="linenum">20</span><br></span>
<span class="i0">She shall be married to this noble earl.<a class="fnanchor pginternal" href="#Footnote_1015_1015">[1015]</a><br></span>
<span class="i0">Will you be ready? do you like this haste?<a class="fnanchor pginternal" href="#Footnote_1015_1015">[1015]</a><br></span>
<span class="i0">We'll keep no great ado; a friend or two;<a id="FNanchor_1017_1017"></a><a class="fnanchor pginternal" href="#Footnote_1017_1017">[1017]</a><br></span>
<span class="i0">For, hark you, Tybalt being slain so late,<br></span>
<span class="i0">It may be thought we held him carelessly,                           <span class="linenum">25</span><br></span>
<span class="i0">Being our kinsman, if we revel much:<br></span>
<span class="i0">Therefore we'll have some half-a-dozen friends,<br></span>
<span class="i0">And there an end. But what say you to Thursday?<a id="FNanchor_1018_1018"></a><a class="fnanchor pginternal" href="#Footnote_1018_1018">[1018]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Par.</i> My lord, I would that Thursday were to-morrow.<a id="FNanchor_1019_1019"></a><a class="fnanchor pginternal" href="#Footnote_1019_1019">[1019]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i> Well, get you gone: o' Thursday be it then.<a id="FNanchor_1020_1020"></a><a class="fnanchor pginternal" href="#Footnote_1020_1020">[1020]</a>       <span class="linenum">30</span><br></span>
<span class="i0">Go you to Juliet ere you go to bed,<a id="FNanchor_1021_1021"></a><a class="fnanchor pginternal" href="#Footnote_1021_1021">[1021]</a><br></span>
<span class="i0">Prepare her, wife, against this wedding-day.<br></span>
<span class="i0">Farewell, my lord. Light to my chamber, ho!<br></span>
<span class="i0">Afore me, it is so very very late,<a id="FNanchor_1022_1022"></a><a class="fnanchor pginternal" href="#Footnote_1022_1022">[1022]</a><br></span>
<span class="i0">That we may call it early by and by:<a class="fnanchor pginternal" href="#Footnote_1022_1022">[1022]</a><a id="FNanchor_1023_1023"></a><a class="fnanchor pginternal" href="#Footnote_1023_1023">[1023]</a>                   <span class="linenum">35</span><br></span>
<span class="i0">Good night.<a id="FNanchor_1024_1024"></a><a class="fnanchor pginternal" href="#Footnote_1024_1024">[1024]</a>               <span class="directline">[<i>Exeunt.</i><br></span></span>
</div></div>

<p><span class="pagenum"><a id="Page_88">[Pg 88]</a></span></p>
<h3><span class="smcap">Scene V.</span> <span class="smcap">Capulet's orchard.</span><a id="FNanchor_1025_1025"></a><a class="fnanchor pginternal" href="#Footnote_1025_1025">[1025]</a></h3>

<p class="directcenter"><i>Enter</i> <span class="smcap">Romeo</span> <i>and</i> <span class="smcap">Juliet</span>, <i>above, at the window</i>.<a id="FNanchor_1026_1026"></a><a class="fnanchor pginternal" href="#Footnote_1026_1026">[1026]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Jul.</i> Wilt thou be gone? it is not yet near day:<a id="FNanchor_1027_1027"></a><a class="fnanchor pginternal" href="#Footnote_1027_1027">[1027]</a><br></span>
<span class="i0">It was the nightingale, and not the lark,<br></span>
<span class="i0">That pierced the fearful hollow of thine ear;<br></span>
<span class="i0">Nightly she sings on yond pomegranate-tree:<a id="FNanchor_1028_1028"></a><a class="fnanchor pginternal" href="#Footnote_1028_1028">[1028]</a><br></span>
<span class="i0">Believe me, love, it was the nightingale.                            <span class="linenum">5</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> It was the lark, the herald of the morn,<a id="FNanchor_1029_1029"></a><a class="fnanchor pginternal" href="#Footnote_1029_1029">[1029]</a><br></span>
<span class="i0">No nightingale: look, love, what envious streaks<br></span>
<span class="i0">Do lace the severing clouds in yonder east:<br></span>
<span class="i0">Night's candles are burnt out, and jocund day<a id="FNanchor_1030_1030"></a><a class="fnanchor pginternal" href="#Footnote_1030_1030">[1030]</a><br></span>
<span class="i0">Stands tiptoe on the misty mountain tops:<a id="FNanchor_1031_1031"></a><a class="fnanchor pginternal" href="#Footnote_1031_1031">[1031]</a>                     <span class="linenum">10</span><br></span>
<span class="i0">I must be gone and live, or stay and die.<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Yond light is not day-light, I know it, I:<a id="FNanchor_1032_1032"></a><a class="fnanchor pginternal" href="#Footnote_1032_1032">[1032]</a><br></span>
<span class="i0">It is some meteor that the sun exhales,<a id="FNanchor_1033_1033"></a><a class="fnanchor pginternal" href="#Footnote_1033_1033">[1033]</a><br></span>
<span class="i0">To be to thee this night a torch-bearer,<br></span>
<span class="i0">And light thee on thy way to Mantua:                                <span class="linenum">15</span><br></span>
<span class="i0">Therefore stay yet; thou need'st not to be gone.<a id="FNanchor_1034_1034"></a><a class="fnanchor pginternal" href="#Footnote_1034_1034">[1034]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Let me be ta'en, let me be put to death;<a id="FNanchor_1035_1035"></a><a class="fnanchor pginternal" href="#Footnote_1035_1035">[1035]</a><br></span>
<span class="i0">I am content, so thou wilt have it so.<a class="fnanchor pginternal" href="#Footnote_1035_1035">[1035]</a><br></span>
<span class="i0">I'll say yon grey is not the morning's eye,<a class="fnanchor pginternal" href="#Footnote_1035_1035">[1035]</a><a id="FNanchor_1036_1036"></a><a class="fnanchor pginternal" href="#Footnote_1036_1036">[1036]</a><br></span><span class="pagenum"><a id="Page_89">[Pg 89]</a></span>
<span class="i0">'Tis but the pale reflex of Cynthia's brow;<a class="fnanchor pginternal" href="#Footnote_1035_1035">[1035]</a><a id="FNanchor_1037_1037"></a><a class="fnanchor pginternal" href="#Footnote_1037_1037">[1037]</a>            <span class="linenum">20</span><br></span>
<span class="i0">Nor that is not the lark, whose notes do beat<a class="fnanchor pginternal" href="#Footnote_1035_1035">[1035]</a><a id="FNanchor_1038_1038"></a><a class="fnanchor pginternal" href="#Footnote_1038_1038">[1038]</a><br></span>
<span class="i0">The vaulty heaven so high above our heads:<a class="fnanchor pginternal" href="#Footnote_1035_1035">[1035]</a><a id="FNanchor_1039_1039"></a><a class="fnanchor pginternal" href="#Footnote_1039_1039">[1039]</a><br></span>
<span class="i0">I have more care to stay than will to go:<a class="fnanchor pginternal" href="#Footnote_1035_1035">[1035]</a><a id="FNanchor_1040_1040"></a><a class="fnanchor pginternal" href="#Footnote_1040_1040">[1040]</a><br></span>
<span class="i0">Come, death, and welcome! Juliet wills it so.<br></span>
<span class="i0">How is't, my soul? let's talk: it is not day.<a id="FNanchor_1041_1041"></a><a class="fnanchor pginternal" href="#Footnote_1041_1041">[1041]</a>                 <span class="linenum">25</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> It is, it is: hie hence, be gone, away!<br></span>
<span class="i0">It is the lark that sings so out of tune,<br></span>
<span class="i0">Straining harsh discords and unpleasing sharps.<br></span>
<span class="i0">Some say the lark makes sweet division;<br></span>
<span class="i0">This doth not so, for she divideth us:                              <span class="linenum">30</span><br></span>
<span class="i0">Some say the lark and loathed toad change eyes;<a id="FNanchor_1042_1042"></a><a class="fnanchor pginternal" href="#Footnote_1042_1042">[1042]</a><br></span>
<span class="i0">O, now I would they had changed voices too!<a id="FNanchor_1043_1043"></a><a class="fnanchor pginternal" href="#Footnote_1043_1043">[1043]</a><br></span>
<span class="i0">Since arm from arm that voice doth us affray,<a id="FNanchor_1044_1044"></a><a class="fnanchor pginternal" href="#Footnote_1044_1044">[1044]</a><br></span>
<span class="i0">Hunting thee hence with hunts-up to the day.<a class="fnanchor pginternal" href="#Footnote_1044_1044">[1044]</a><a id="FNanchor_1045_1045"></a><a class="fnanchor pginternal" href="#Footnote_1045_1045">[1045]</a><br></span>
<span class="i0">O, now be gone; more light and light it grows.<a id="FNanchor_1046_1046"></a><a class="fnanchor pginternal" href="#Footnote_1046_1046">[1046]</a>                <span class="linenum">35</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> More light and light: more dark and dark our woes!<a id="FNanchor_1047_1047"></a><a class="fnanchor pginternal" href="#Footnote_1047_1047">[1047]</a><br></span>
</div></div>

<p class="directcenter"><i>Enter</i> <span class="smcap">Nurse</span>, <i>to the chamber</i>.<a id="FNanchor_1048_1048"></a><a class="fnanchor pginternal" href="#Footnote_1048_1048">[1048]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Nurse.</i> Madam!<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Nurse?<a id="FNanchor_1049_1049"></a><a class="fnanchor pginternal" href="#Footnote_1049_1049">[1049]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Your lady mother is coming to your chamber:<br></span>
<span class="i0">The day is broke; be wary, look about.<a id="FNanchor_1050_1050"></a><a class="fnanchor pginternal" href="#Footnote_1050_1050">[1050]</a>      <span class="directline">[<i>Exit.</i>     <span class="linenum">40</span><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Then, window, let day in, and let life out.<a id="FNanchor_1051_1051"></a><a class="fnanchor pginternal" href="#Footnote_1051_1051">[1051]</a><br></span>
<span class="pagenum"><a id="Page_90">[Pg 90]</a></span></div><div class="stanza">
<span class="i0"><i>Rom.</i> Farewell, farewell! one kiss, and I'll descend.<a id="FNanchor_1052_1052"></a><a class="fnanchor pginternal" href="#Footnote_1052_1052">[1052]</a><br></span>
</div></div>

<p class="directright">[<i>Descends.</i><a id="FNanchor_1053_1053"></a><a class="fnanchor pginternal" href="#Footnote_1053_1053">[1053]</a></p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Jul.</i> Art thou gone so? my lord, my love, my friend!<a id="FNanchor_1054_1054"></a><a class="fnanchor pginternal" href="#Footnote_1054_1054">[1054]</a><br></span>
<span class="i0">I must hear from thee every day in the hour,<a id="FNanchor_1055_1055"></a><a class="fnanchor pginternal" href="#Footnote_1055_1055">[1055]</a><br></span>
<span class="i0">For in a minute there are many days:                                <span class="linenum">45</span><br></span>
<span class="i0">O, by this count I shall be much in years<br></span>
<span class="i0">Ere I again behold my Romeo!<br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> Farewell!<a id="FNanchor_1056_1056"></a><a class="fnanchor pginternal" href="#Footnote_1056_1056">[1056]</a><br></span>
<span class="i0">I will omit no opportunity<a class="fnanchor pginternal" href="#Footnote_1056_1056">[1056]</a><br></span>
<span class="i0">That may convey my greetings, love, to thee.                        <span class="linenum">50</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O, think'st thou we shall ever meet again?<a id="FNanchor_1057_1057"></a><a class="fnanchor pginternal" href="#Footnote_1057_1057">[1057]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> I doubt it not; and all these woes shall serve<br></span>
<span class="i0">For sweet discourses in our time to come.<a id="FNanchor_1058_1058"></a><a class="fnanchor pginternal" href="#Footnote_1058_1058">[1058]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O God! I have an ill-divining soul.<a id="FNanchor_1059_1059"></a><a class="fnanchor pginternal" href="#Footnote_1059_1059">[1059]</a><br></span>
<span class="i0">Methinks I see thee, now thou art below,<a id="FNanchor_1060_1060"></a><a class="fnanchor pginternal" href="#Footnote_1060_1060">[1060]</a>                      <span class="linenum">55</span><br></span>
<span class="i0">As one dead in the bottom of a tomb:<a id="FNanchor_1061_1061"></a><a class="fnanchor pginternal" href="#Footnote_1061_1061">[1061]</a><br></span>
<span class="i0">Either my eyesight fails or thou look'st pale.<a id="FNanchor_1062_1062"></a><a class="fnanchor pginternal" href="#Footnote_1062_1062">[1062]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Rom.</i> And trust me, love, in my eye so do you:<a id="FNanchor_1063_1063"></a><a class="fnanchor pginternal" href="#Footnote_1063_1063">[1063]</a><br></span>
<span class="i0">Dry sorrow drinks our blood. Adieu, adieu!<a id="FNanchor_1064_1064"></a><a class="fnanchor pginternal" href="#Footnote_1064_1064">[1064]</a>      <span class="directline">[<i>Exit.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O fortune, fortune! all men call thee fickle:<a id="FNanchor_1065_1065"></a><a class="fnanchor pginternal" href="#Footnote_1065_1065">[1065]</a>     <span class="linenum">60</span><br></span>
<span class="i0">If thou art fickle, what dost thou with him<br></span>
<span class="i0">That is renown'd for faith? Be fickle, fortune;<a id="FNanchor_1066_1066"></a><a class="fnanchor pginternal" href="#Footnote_1066_1066">[1066]</a><br></span>
<span class="i0">For then, I hope, thou wilt not keep him long,<br></span>
<span class="i0">But send him back.<a id="FNanchor_1067_1067"></a><a class="fnanchor pginternal" href="#Footnote_1067_1067">[1067]</a><br></span>
<span class="pagenum"><a id="Page_91">[Pg 91]</a></span></div><div class="stanza">
<span class="i0"><i>La. Cap.</i> [<i>Within</i>] Ho, daughter! are you up?<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Who is't that calls? it is my lady mother!<a id="FNanchor_1068_1068"></a><a class="fnanchor pginternal" href="#Footnote_1068_1068">[1068]</a>        <span class="linenum">65</span><br></span>
<span class="i0">Is she not down so late, or up so early?<a id="FNanchor_1069_1069"></a><a class="fnanchor pginternal" href="#Footnote_1069_1069">[1069]</a><br></span>
<span class="i0">What unaccustom'd cause procures her hither?<a id="FNanchor_1070_1070"></a><a class="fnanchor pginternal" href="#Footnote_1070_1070">[1070]</a><br></span>
</div></div>

<p class="directcenter"><i>Enter</i> <span class="smcap">Lady Capulet</span>.<a id="FNanchor_1071_1071"></a><a class="fnanchor pginternal" href="#Footnote_1071_1071">[1071]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>La. Cap.</i> Why, how now, Juliet!<a id="FNanchor_1072_1072"></a><a class="fnanchor pginternal" href="#Footnote_1072_1072">[1072]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i>                           Madam, I am not well.<br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Evermore weeping for your cousin's death?<br></span>
<span class="i0">What, wilt thou wash him from his grave with tears?                 <span class="linenum">70</span><br></span>
<span class="i0">An if thou couldst, thou couldst not make him live;<a id="FNanchor_1073_1073"></a><a class="fnanchor pginternal" href="#Footnote_1073_1073">[1073]</a><a id="FNanchor_1074_1074"></a><a class="fnanchor pginternal" href="#Footnote_1074_1074">[1074]</a><br></span>
<span class="i0">Therefore have done: some grief shows much of love.<a class="fnanchor pginternal" href="#Footnote_1073_1073">[1073]</a><br></span>
<span class="i0">But much of grief shows still some want of wit.<a class="fnanchor pginternal" href="#Footnote_1073_1073">[1073]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Yet let me weep for such a feeling loss.<br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> So shall you feel the loss, but not the friend<a id="FNanchor_1075_1075"></a><a class="fnanchor pginternal" href="#Footnote_1075_1075">[1075]</a><a id="FNanchor_1076_1076"></a><a class="fnanchor pginternal" href="#Footnote_1076_1076">[1076]</a><span class="linenum">75</span><br></span>
<span class="i0">Which you weep for.<a class="fnanchor pginternal" href="#Footnote_1076_1076">[1076]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i>              Feeling so the loss,<a class="fnanchor pginternal" href="#Footnote_1076_1076">[1076]</a><br></span>
<span class="i0">I cannot choose but ever weep the friend.<a class="fnanchor pginternal" href="#Footnote_1076_1076">[1076]</a><a id="FNanchor_1077_1077"></a><a class="fnanchor pginternal" href="#Footnote_1077_1077">[1077]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Well, girl, thou weep'st not so much for his death<br></span>
<span class="i0">As that the villain lives which slaughter'd him.<a id="FNanchor_1078_1078"></a><a class="fnanchor pginternal" href="#Footnote_1078_1078">[1078]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> What villain, madam?<br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i>                  That same villain, Romeo.<a id="FNanchor_1079_1079"></a><a class="fnanchor pginternal" href="#Footnote_1079_1079">[1079]</a>    <span class="linenum">80</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> [<i>Aside</i>] Villain and he be many miles asunder.<a id="FNanchor_1080_1080"></a><a class="fnanchor pginternal" href="#Footnote_1080_1080">[1080]</a><br></span>
<span class="i0">God pardon him! I do, with all my heart;<a id="FNanchor_1081_1081"></a><a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1082_1082"></a><a class="fnanchor pginternal" href="#Footnote_1082_1082">[1082]</a><br></span>
<span class="i0">And yet no man like he doth grieve my heart.<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> That is because the traitor murderer lives.<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1083_1083"></a><a class="fnanchor pginternal" href="#Footnote_1083_1083">[1083]</a><br></span>
<span class="pagenum"><a id="Page_92">[Pg 92]</a></span></div><div class="stanza">
<span class="i0"><i>Jul.</i> Ay, madam, from the reach of these my hands:<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a>     <span class="linenum">85</span><br></span>
<span class="i0">Would none but I might venge my cousin's death!<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> We will have vengeance for it, fear thou not:<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">Then weep no more. I'll send to one in Mantua,<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">Where that same banish'd runagate doth live,<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">Shall give him such an unaccustom'd dram<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1084_1084"></a><a class="fnanchor pginternal" href="#Footnote_1084_1084">[1084]</a>               <span class="linenum">90</span><br></span>
<span class="i0">That he shall soon keep Tybalt company:<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">And then, I hope, thou wilt be satisfied.<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Indeed, I never shall be satisfied<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">With Romeo, till I behold him—dead—<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1085_1085"></a><a class="fnanchor pginternal" href="#Footnote_1085_1085">[1085]</a><br></span>
<span class="i0">Is my poor heart so for a kinsman vex'd.<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1086_1086"></a><a class="fnanchor pginternal" href="#Footnote_1086_1086">[1086]</a>               <span class="linenum">95</span><br></span>
<span class="i0">Madam, if you could find out but a man<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">To bear a poison, I would temper it,<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1087_1087"></a><a class="fnanchor pginternal" href="#Footnote_1087_1087">[1087]</a><br></span>
<span class="i0">That Romeo should, upon receipt thereof,<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">Soon sleep in quiet. O, how my heart abhors<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><br></span>
<span class="i0">To hear him named, and cannot come to him,<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a>                  <span class="linenum">100</span><br></span>
<span class="i0">To wreak the love I bore my cousin<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1088_1088"></a><a class="fnanchor pginternal" href="#Footnote_1088_1088">[1088]</a><br></span>
<span class="i0">Upon his body that hath slaughter'd him!<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1089_1089"></a><a class="fnanchor pginternal" href="#Footnote_1089_1089">[1089]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Find thou the means, and I'll find such a man.<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1090_1090"></a><a class="fnanchor pginternal" href="#Footnote_1090_1090">[1090]</a><br></span>
<span class="i0">But now I'll tell thee joyful tidings, girl.<a class="fnanchor pginternal" href="#Footnote_1081_1081">[1081]</a><a id="FNanchor_1091_1091"></a><a class="fnanchor pginternal" href="#Footnote_1091_1091">[1091]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> And joy comes well in such a needy time:<a id="FNanchor_1092_1092"></a><a class="fnanchor pginternal" href="#Footnote_1092_1092">[1092]</a>         <span class="linenum">105</span><br></span>
<span class="i0">What are they, I beseech your ladyship?<a id="FNanchor_1093_1093"></a><a class="fnanchor pginternal" href="#Footnote_1093_1093">[1093]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Well, well, thou hast a careful father, child;<br></span>
<span class="i0">One who, to put thee from thy heaviness,<br></span>
<span class="i0">Hath sorted out a sudden day of joy,<br></span>
<span class="i0">That thou expect'st not, nor I look'd not for.<a id="FNanchor_1094_1094"></a><a class="fnanchor pginternal" href="#Footnote_1094_1094">[1094]</a>               <span class="linenum">110</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Madam, in happy time, what day is that?<a id="FNanchor_1095_1095"></a><a class="fnanchor pginternal" href="#Footnote_1095_1095">[1095]</a><br></span>
<span class="pagenum"><a id="Page_93">[Pg 93]</a></span></div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Marry, my child, early next Thursday morn,<br></span>
<span class="i0">The gallant, young, and noble gentleman,<br></span>
<span class="i0">The County Paris, at Saint Peter's Church,<a id="FNanchor_1096_1096"></a><a class="fnanchor pginternal" href="#Footnote_1096_1096">[1096]</a><br></span>
<span class="i0">Shall happily make thee there a joyful bride.<a id="FNanchor_1097_1097"></a><a class="fnanchor pginternal" href="#Footnote_1097_1097">[1097]</a>                <span class="linenum">115</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Now, by Saint Peter's Church, and Peter too,<a id="FNanchor_1098_1098"></a><a class="fnanchor pginternal" href="#Footnote_1098_1098">[1098]</a><br></span>
<span class="i0">He shall not make me there a joyful bride.<br></span>
<span class="i0">I wonder at this haste; that I must wed<br></span>
<span class="i0">Ere he that should be husband comes to woo.<a id="FNanchor_1099_1099"></a><a class="fnanchor pginternal" href="#Footnote_1099_1099">[1099]</a><br></span>
<span class="i0">I pray you, tell my lord and father, madam,                        <span class="linenum">120</span><br></span>
<span class="i0">I will not marry yet; and, when I do, I swear,<a id="FNanchor_1100_1100"></a><a class="fnanchor pginternal" href="#Footnote_1100_1100">[1100]</a><br></span>
<span class="i0">It shall be Romeo, whom you know I hate,<br></span>
<span class="i0">Rather than Paris. These are news indeed!<a id="FNanchor_1101_1101"></a><a class="fnanchor pginternal" href="#Footnote_1101_1101">[1101]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Here comes your father; tell him so yourself,<a id="FNanchor_1102_1102"></a><a class="fnanchor pginternal" href="#Footnote_1102_1102">[1102]</a><br></span>
<span class="i0">And see how he will take it at your hands.<a id="FNanchor_1103_1103"></a><a class="fnanchor pginternal" href="#Footnote_1103_1103">[1103]</a>                   <span class="linenum">125</span><br></span>
</div></div>

<p class="directcenter"><i>Enter</i> <span class="smcap">Capulet</span> <i>and</i> Nurse.<a id="FNanchor_1104_1104"></a><a class="fnanchor pginternal" href="#Footnote_1104_1104">[1104]</a>
</p>

<div class="poem"><div class="stanza">
<span class="i0"><i>Cap.</i> When the sun sets, the air doth drizzle dew;<a id="FNanchor_1105_1105"></a><a class="fnanchor pginternal" href="#Footnote_1105_1105">[1105]</a><a id="FNanchor_1106_1106"></a><a class="fnanchor pginternal" href="#Footnote_1106_1106">[1106]</a><br></span>
<span class="i0">But for the sunset of my brother's son<a class="fnanchor pginternal" href="#Footnote_1105_1105">[1105]</a><br></span>
<span class="i0">It rains downright.<a class="fnanchor pginternal" href="#Footnote_1105_1105">[1105]</a><a id="FNanchor_1107_1107"></a><a class="fnanchor pginternal" href="#Footnote_1107_1107">[1107]</a><br></span>
<span class="i0">How now! a conduit, girl? what, still in tears?<a class="fnanchor pginternal" href="#Footnote_1107_1107">[1107]</a><br></span>
<span class="i0">Evermore showering? In one little body<a id="FNanchor_1108_1108"></a><a class="fnanchor pginternal" href="#Footnote_1108_1108">[1108]</a>                       <span class="linenum">130</span><br></span>
<span class="i0">Thou counterfeit'st a bark, a sea, a wind:<a id="FNanchor_1109_1109"></a><a class="fnanchor pginternal" href="#Footnote_1109_1109">[1109]</a><br></span>
<span class="i0">For still thy eyes, which I may call the sea,<br></span>
<span class="i0">Do ebb and flow with tears; the bark thy body is,<a id="FNanchor_1110_1110"></a><a class="fnanchor pginternal" href="#Footnote_1110_1110">[1110]</a><br></span><span class="pagenum"><a id="Page_94">[Pg 94]</a></span>
<span class="i0">Sailing in this salt flood; the winds, thy sighs;<br></span>
<span class="i0">Who raging with thy tears, and they with them,<a id="FNanchor_1111_1111"></a><a class="fnanchor pginternal" href="#Footnote_1111_1111">[1111]</a>               <span class="linenum">135</span><br></span>
<span class="i0">Without a sudden calm will overset<br></span>
<span class="i0">Thy tempest-tossed body. How now, wife!<a id="FNanchor_1112_1112"></a><a class="fnanchor pginternal" href="#Footnote_1112_1112">[1112]</a><br></span>
<span class="i0">Have you deliver'd to her our decree?<a id="FNanchor_1113_1113"></a><a class="fnanchor pginternal" href="#Footnote_1113_1113">[1113]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Ay, sir; but she will none, she gives you thanks.<a id="FNanchor_1114_1114"></a><a class="fnanchor pginternal" href="#Footnote_1114_1114">[1114]</a><br></span>
<span class="i0">I would the fool were married to her grave!                        <span class="linenum">140</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i> Soft! take me with you, take me with you, wife.<br></span>
<span class="i0">How! will she none? doth she not give us thanks?<a id="FNanchor_1115_1115"></a><a class="fnanchor pginternal" href="#Footnote_1115_1115">[1115]</a><br></span>
<span class="i0">Is she not proud? doth she not count her blest,<br></span>
<span class="i0">Unworthy as she is, that we have wrought<br></span>
<span class="i0">So worthy a gentleman to be her bridegroom?<a id="FNanchor_1116_1116"></a><a class="fnanchor pginternal" href="#Footnote_1116_1116">[1116]</a>                  <span class="linenum">145</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Not proud, you have, but thankful that you have:<a id="FNanchor_1117_1117"></a><a class="fnanchor pginternal" href="#Footnote_1117_1117">[1117]</a><br></span>
<span class="i0">Proud can I never be of what I hate;<a id="FNanchor_1118_1118"></a><a class="fnanchor pginternal" href="#Footnote_1118_1118">[1118]</a><br></span>
<span class="i0">But thankful even for hate that is meant love.<a id="FNanchor_1119_1119"></a><a class="fnanchor pginternal" href="#Footnote_1119_1119">[1119]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i> How, how! how, how! chop-logic! What is this?<a id="FNanchor_1120_1120"></a><a class="fnanchor pginternal" href="#Footnote_1120_1120">[1120]</a><br></span>
<span class="i0">'Proud,' and 'I thank you,' and 'I thank you not;'<a id="FNanchor_1121_1121"></a><a class="fnanchor pginternal" href="#Footnote_1121_1121">[1121]</a>           <span class="linenum">150</span><br></span>
<span class="i0">And yet 'not proud:' mistress minion, you,<a class="fnanchor pginternal" href="#Footnote_1121_1121">[1121]</a><a id="FNanchor_1122_1122"></a><a class="fnanchor pginternal" href="#Footnote_1122_1122">[1122]</a><br></span>
<span class="i0">Thank me no thankings, nor proud me no prouds,<br></span>
<span class="i0">But fettle your fine joints 'gainst Thursday next,<a id="FNanchor_1123_1123"></a><a class="fnanchor pginternal" href="#Footnote_1123_1123">[1123]</a><br></span>
<span class="i0">To go with Paris to Saint Peter's Church,<br></span>
<span class="i0">Or I will drag thee on a hurdle thither.                           <span class="linenum">155</span><br></span><span class="pagenum"><a id="Page_95">[Pg 95]</a></span>
<span class="i0">Out, you green-sickness carrion! out, you baggage!<a id="FNanchor_1124_1124"></a><a class="fnanchor pginternal" href="#Footnote_1124_1124">[1124]</a><a id="FNanchor_1125_1125"></a><a class="fnanchor pginternal" href="#Footnote_1125_1125">[1125]</a><br></span>
<span class="i0">You tallow-face!<a class="fnanchor pginternal" href="#Footnote_1124_1124">[1124]</a><a id="FNanchor_1126_1126"></a><a class="fnanchor pginternal" href="#Footnote_1126_1126">[1126]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i>       Fie, fie! what, are you mad?<br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Good father, I beseech you on my knees,<br></span>
<span class="i0">Hear me with patience but to speak a word.<br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i> Hang thee, young baggage! disobedient wretch!<a id="FNanchor_1127_1127"></a><a class="fnanchor pginternal" href="#Footnote_1127_1127">[1127]</a>    <span class="linenum">160</span><br></span>
<span class="i0">I tell thee what: get thee to church o' Thursday,<a id="FNanchor_1128_1128"></a><a class="fnanchor pginternal" href="#Footnote_1128_1128">[1128]</a><br></span>
<span class="i0">Or never after look me in the face:<br></span>
<span class="i0">Speak not, reply not, do not answer me;<br></span>
<span class="i0">My fingers itch. Wife, we scarce thought us blest<a id="FNanchor_1129_1129"></a><a class="fnanchor pginternal" href="#Footnote_1129_1129">[1129]</a><br></span>
<span class="i0">That God had lent us but this only child,<a id="FNanchor_1130_1130"></a><a class="fnanchor pginternal" href="#Footnote_1130_1130">[1130]</a>                    <span class="linenum">165</span><br></span>
<span class="i0">But now I see this one is one too much<br></span>
<span class="i0">And that we have a curse in having her:<a id="FNanchor_1131_1131"></a><a class="fnanchor pginternal" href="#Footnote_1131_1131">[1131]</a><br></span>
<span class="i0">Out on her, hilding!<br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i>             God in heaven bless her!<br></span>
<span class="i0">You are to blame, my lord, to rate her so.<a id="FNanchor_1132_1132"></a><a class="fnanchor pginternal" href="#Footnote_1132_1132">[1132]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i> And why, my lady wisdom? hold your tongue,<a class="fnanchor pginternal" href="#Footnote_1127_1127">[1127]</a>      <span class="linenum">170</span><br></span>
<span class="i0">Good prudence; smatter with your gossips, go.<a id="FNanchor_1133_1133"></a><a class="fnanchor pginternal" href="#Footnote_1133_1133">[1133]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> I speak no treason.<a id="FNanchor_1134_1134"></a><a class="fnanchor pginternal" href="#Footnote_1134_1134">[1134]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i>                       O, God ye god-den.<a class="fnanchor pginternal" href="#Footnote_1127_1127">[1127]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> May not one speak?<br></span>
</div><div class="stanza">
<span class="i0"><i>Cap.</i>                      Peace, you mumbling fool!<a id="FNanchor_1135_1135"></a><a class="fnanchor pginternal" href="#Footnote_1135_1135">[1135]</a><br></span>
<span class="i0">Utter your gravity o'er a gossip's bowl;<a id="FNanchor_1136_1136"></a><a class="fnanchor pginternal" href="#Footnote_1136_1136">[1136]</a><br></span>
<span class="i0">For here we need it not.<br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i>               You are too hot.                     <span class="linenum">175</span><br></span>
<span class="pagenum"><a id="Page_96">[Pg 96]</a></span></div><div class="stanza">
<span class="i0"><i>Cap.</i> God's bread! it makes me mad:<a class="fnanchor pginternal" href="#Footnote_1127_1127">[1127]</a><a id="FNanchor_1137_1137"></a><a class="fnanchor pginternal" href="#Footnote_1137_1137">[1137]</a><a id="FNanchor_1138_1138"></a><a class="fnanchor pginternal" href="#Footnote_1138_1138">[1138]</a><br></span>
<span class="i0">Day, night, hour, tide, time, work, play,<a class="fnanchor pginternal" href="#Footnote_1137_1137">[1137]</a><a class="fnanchor pginternal" href="#Footnote_1138_1138">[1138]</a><a id="FNanchor_1139_1139"></a><a class="fnanchor pginternal" href="#Footnote_1139_1139">[1139]</a><br></span>
<span class="i0">Alone, in company, still my care hath been<a class="fnanchor pginternal" href="#Footnote_1137_1137">[1137]</a><br></span>
<span class="i0">To have her match'd: and having now provided<br></span>
<span class="i0">A gentleman of noble parentage,<a id="FNanchor_1140_1140"></a><a class="fnanchor pginternal" href="#Footnote_1140_1140">[1140]</a>                              <span class="linenum">180</span><br></span>
<span class="i0">Of fair demesnes, youthful, and nobly train'd,<a id="FNanchor_1141_1141"></a><a class="fnanchor pginternal" href="#Footnote_1141_1141">[1141]</a><br></span>
<span class="i0">Stuff'd, as they say, with honourable parts,<br></span>
<span class="i0">Proportion'd as one's thought would wish a man;<a id="FNanchor_1142_1142"></a><a class="fnanchor pginternal" href="#Footnote_1142_1142">[1142]</a><br></span>
<span class="i0">And then to have a wretched puling fool,<br></span>
<span class="i0">A whining mammet, in her fortune's tender,<a id="FNanchor_1143_1143"></a><a class="fnanchor pginternal" href="#Footnote_1143_1143">[1143]</a>                   <span class="linenum">185</span><br></span>
<span class="i0">To answer 'I'll not wed; I cannot love,<br></span>
<span class="i0">I am too young; I pray you, pardon me.'<br></span>
<span class="i0">But, an you will not wed, I'll pardon you:<a id="FNanchor_1144_1144"></a><a class="fnanchor pginternal" href="#Footnote_1144_1144">[1144]</a><br></span>
<span class="i0">Graze where you will, you shall not house with me:<br></span>
<span class="i0">Look to't, think on't, I do not use to jest.                       <span class="linenum">190</span><br></span>
<span class="i0">Thursday is near; lay hand on heart, advise:<br></span>
<span class="i0">An you be mine, I'll give you to my friend;<a id="FNanchor_1145_1145"></a><a class="fnanchor pginternal" href="#Footnote_1145_1145">[1145]</a><br></span>
<span class="i0">An you be not, hang, beg, starve, die in the streets,<a class="fnanchor pginternal" href="#Footnote_1145_1145">[1145]</a><a id="FNanchor_1146_1146"></a><a class="fnanchor pginternal" href="#Footnote_1146_1146">[1146]</a><br></span>
<span class="i0">For, by my soul, I'll ne'er acknowledge thee,<br></span>
<span class="i0">Nor what is mine shall never do thee good:<a id="FNanchor_1147_1147"></a><a class="fnanchor pginternal" href="#Footnote_1147_1147">[1147]</a>                   <span class="linenum">195</span><br></span>
<span class="i0">Trust to't, bethink you; I'll not be forsworn.             <span class="directline">[<i>Exit.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Is there no pity sitting in the clouds,<br></span>
<span class="i0">That sees into the bottom of my grief?<br></span>
<span class="i0">O, sweet my mother, cast me not away!<br></span>
<span class="i0">Delay this marriage for a month, a week;                           <span class="linenum">200</span><br></span><span class="pagenum"><a id="Page_97">[Pg 97]</a></span>
<span class="i0">Or, if you do not, make the bridal bed<br></span>
<span class="i0">In that dim monument where Tybalt lies.<a id="FNanchor_1148_1148"></a><a class="fnanchor pginternal" href="#Footnote_1148_1148">[1148]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>La. Cap.</i> Talk not to me, for I'll not speak a word:<br></span>
<span class="i0">Do as thou wilt, for I have done with thee.                <span class="directline">[<i>Exit.</i><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> O God!—O nurse, how shall this be prevented?<a id="FNanchor_1149_1149"></a><a class="fnanchor pginternal" href="#Footnote_1149_1149">[1149]</a>    <span class="linenum">205</span><br></span>
<span class="i0">My husband is on earth, my faith in heaven;<a id="FNanchor_1150_1150"></a><a class="fnanchor pginternal" href="#Footnote_1150_1150">[1150]</a><br></span>
<span class="i0">How shall that faith return again to earth,<a class="fnanchor pginternal" href="#Footnote_1150_1150">[1150]</a><br></span>
<span class="i0">Unless that husband send it me from heaven<a class="fnanchor pginternal" href="#Footnote_1150_1150">[1150]</a><br></span>
<span class="i0">By leaving earth? comfort me, counsel me.<a class="fnanchor pginternal" href="#Footnote_1150_1150">[1150]</a><br></span>
<span class="i0">Alack, alack, that heaven should practise stratagems<a id="FNanchor_1151_1151"></a><a class="fnanchor pginternal" href="#Footnote_1151_1151">[1151]</a>         <span class="linenum">210</span><br></span>
<span class="i0">Upon so soft a subject as myself!<br></span>
<span class="i0">What say'st thou? hast thou not a word of joy?<a id="FNanchor_1152_1152"></a><a class="fnanchor pginternal" href="#Footnote_1152_1152">[1152]</a><br></span>
<span class="i0">Some comfort, nurse.<a class="fnanchor pginternal" href="#Footnote_1152_1152">[1152]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i>             Faith, here it is.<a id="FNanchor_1153_1153"></a><a class="fnanchor pginternal" href="#Footnote_1153_1153">[1153]</a><br></span>
<span class="i0">Romeo is banish'd, and all the world to nothing,<a class="fnanchor pginternal" href="#Footnote_1153_1153">[1153]</a><a id="FNanchor_1154_1154"></a><a class="fnanchor pginternal" href="#Footnote_1154_1154">[1154]</a><br></span>
<span class="i0">That he dares ne'er come back to challenge you;                    <span class="linenum">215</span><br></span>
<span class="i0">Or, if he do, it needs must be by stealth.<a id="FNanchor_1155_1155"></a><a class="fnanchor pginternal" href="#Footnote_1155_1155">[1155]</a><br></span>
<span class="i0">Then, since the case so stands as now it doth,<br></span>
<span class="i0">I think it best you married with the county.<a id="FNanchor_1156_1156"></a><a class="fnanchor pginternal" href="#Footnote_1156_1156">[1156]</a><br></span>
<span class="i0">O, he's a lovely gentleman!<a id="FNanchor_1157_1157"></a><a class="fnanchor pginternal" href="#Footnote_1157_1157">[1157]</a><br></span>
<span class="i0">Romeo's a dishclout to him: an eagle, madam,                       <span class="linenum">220</span><br></span>
<span class="i0">Hath not so green, so quick, so fair an eye<a id="FNanchor_1158_1158"></a><a class="fnanchor pginternal" href="#Footnote_1158_1158">[1158]</a><br></span>
<span class="i0">As Paris hath. Beshrew my very heart,<a id="FNanchor_1159_1159"></a><a class="fnanchor pginternal" href="#Footnote_1159_1159">[1159]</a><br></span>
<span class="i0">I think you are happy in this second match,<br></span>
<span class="i0">For it excels your first: or if it did not,<br></span>
<span class="i0">Your first is dead, or 'twere as good he were                      <span class="linenum">225</span><br></span>
<span class="i0">As living here and you no use of him.<a id="FNanchor_1160_1160"></a><a class="fnanchor pginternal" href="#Footnote_1160_1160">[1160]</a><br></span>
<span class="pagenum"><a id="Page_98">[Pg 98]</a></span></div><div class="stanza">
<span class="i0"><i>Jul.</i> Speakest thou from thy heart?<a id="FNanchor_1161_1161"></a><a class="fnanchor pginternal" href="#Footnote_1161_1161">[1161]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> And from my soul too; else beshrew them both.<a id="FNanchor_1162_1162"></a><a class="fnanchor pginternal" href="#Footnote_1162_1162">[1162]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Amen!<br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> What?<a id="FNanchor_1163_1163"></a><a class="fnanchor pginternal" href="#Footnote_1163_1163">[1163]</a>                                          <span class="linenum">230</span><br></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Well, thou hast comforted me marvellous much.<br></span>
<span class="i0">Go in, and tell my lady I am gone,<br></span>
<span class="i0">Having displeased my father, to Laurence' cell,<br></span>
<span class="i0">To make confession and to be absolved.<a id="FNanchor_1164_1164"></a><a class="fnanchor pginternal" href="#Footnote_1164_1164">[1164]</a><br></span>
</div><div class="stanza">
<span class="i0"><i>Nurse.</i> Marry, I will, and this is wisely done.<a id="FNanchor_1165_1165"></a><a class="fnanchor pginternal" href="#Footnote_1165_1165">[1165]</a>      <span class="directline">[<i>Exit.</i><span class="linenum">235</span><br></span></span>
</div><div class="stanza">
<span class="i0"><i>Jul.</i> Ancient damnation! O most wicked fiend!<a id="FNanchor_1166_1166"></a><a class="fnanchor pginternal" href="#Footnote_1166_1166">[1166]</a><br></span>
<span class="i0">Is it more sin to wish me thus forsworn,<a id="FNanchor_1167_1167"></a><a class="fnanchor pginternal" href="#Footnote_1167_1167">[1167]</a><br></span>
<span class="i0">Or to dispraise my lord with that same tongue<br></span>
<span class="i0">Which she hath praised him with above compare<br></span>
<span class="i0">So many thousand times? Go, counsellor;                            <span class="linenum">240</span><br></span>
<span class="i0">Thou and my bosom henceforth shall be twain.<a id="FNanchor_1168_1168"></a><a class="fnanchor pginternal" href="#Footnote_1168_1168">[1168]</a><br></span>
<span class="i0">I'll to the friar, to know his remedy:<br></span>
<span class="i0">If all else fail, myself have power to die.<a id="FNanchor_1169_1169"></a><a class="fnanchor pginternal" href="#Footnote_1169_1169">[1169]</a>      <span class="directline">[<i>Exit.</i><br></span></span>
</div></div>

